-- Aprenda se Divertindo · 92 · Baralho de cartões · trilha Enem · mais 500 cartões (total de 1.000)
-- Rode depois do 91-cartoes-policial-3.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Assuntos novos, conferidos contra os 3.500 cartões já existentes para não repetir, nas 8 matérias do Enem:
-- Linguagens (gêneros, figuras, autores e obras, artes, redação), Matemática (porcentagem, proporção, estatística,
-- probabilidade, contagem, funções, geometria), Biologia, Química, Física, História, Geografia e Filosofia/Sociologia.
-- Os cartões de cálculo trazem a conta na explicação.
-- Cartões numerados de 2.000.003.501 a 2.000.004.000. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000003501, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função da linguagem predomina em um verbete de dicionário?", "verso": "A metalinguística: o código (a língua) explica o próprio código.", "explicacao": "Também aparece em poemas que falam do ato de escrever."}, {"id": 2000003502, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função predomina em um manual de instruções?", "verso": "A conativa (apelativa), com verbos no imperativo, junto com a referencial.", "explicacao": "O foco está no receptor, que deve agir."}, {"id": 2000003503, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função predomina em um texto científico?", "verso": "A referencial (denotativa): informar com objetividade.", "explicacao": "O foco está no assunto (referente)."}, {"id": 2000003504, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é norma-padrão?", "verso": "Modelo idealizado de língua, descrito nas gramáticas normativas, usado como referência em situações formais.", "explicacao": "Diferente da norma culta, que é o uso real das pessoas escolarizadas."}, {"id": 2000003505, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é adequação linguística?", "verso": "Escolher a variedade da língua adequada à situação, ao interlocutor e ao gênero do texto.", "explicacao": "Para o Enem, não existe fala \"errada\", e sim inadequada ao contexto."}, {"id": 2000003506, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é gíria?", "verso": "Vocabulário próprio de um grupo social, como jovens ou profissionais, que marca identidade.", "explicacao": "Exemplo de variação diastrática (social)."}, {"id": 2000003507, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é jargão?", "verso": "Vocabulário técnico de uma profissão ou área, como o \"juridiquês\" ou o \"economês\".", "explicacao": "Pode dificultar a compreensão por leigos."}, {"id": 2000003508, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que são estrangeirismos?", "verso": "Palavras ou expressões de outras línguas usadas no português, como \"delivery\" e \"shopping\".", "explicacao": "Fazem parte da variação e da história da língua."}, {"id": 2000003509, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que são neologismos?", "verso": "Palavras novas criadas na língua, como \"deletar\" e \"printar\", ou criações literárias.", "explicacao": "Guimarães Rosa é famoso pelos neologismos."}, {"id": 2000003510, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "Quais as características de uma carta aberta?", "verso": "Texto argumentativo dirigido a um destinatário (autoridade ou instituição), mas publicado para toda a sociedade, defendendo uma causa.", "explicacao": "Gênero comum em questões de Linguagens."}, {"id": 2000003511, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "Quais as características de um editorial?", "verso": "Texto opinativo que expressa a posição do próprio jornal ou revista, sem assinatura de autor.", "explicacao": "Diferente do artigo de opinião, que é assinado."}, {"id": 2000003512, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um infográfico?", "verso": "Gênero que combina texto, imagens, números e gráficos para explicar uma informação de forma visual.", "explicacao": "Exemplo de texto multimodal."}, {"id": 2000003513, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é uma resenha crítica?", "verso": "Texto que resume e avalia uma obra (livro, filme, exposição), com a opinião fundamentada do autor.", "explicacao": "Mistura descrição e argumentação."}, {"id": 2000003514, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um anúncio publicitário?", "verso": "Texto persuasivo que busca convencer o público a consumir um produto ou aderir a uma ideia, combinando linguagem verbal e visual.", "explicacao": "Predomina a função apelativa."}, {"id": 2000003515, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é o cordel?", "verso": "Literatura popular em versos rimados, vendida em folhetos pendurados em cordas, com xilogravuras na capa.", "explicacao": "Tradição do Nordeste, reconhecida como patrimônio cultural imaterial em 2018."}, {"id": 2000003516, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um meme?", "verso": "Texto multimodal da internet que combina imagem e frase para produzir humor ou crítica, muitas vezes com intertextualidade.", "explicacao": "O sentido depende do contexto e do repertório do leitor."}, {"id": 2000003517, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um texto multimodal?", "verso": "Texto que combina diferentes linguagens (palavras, imagens, cores, sons) para construir sentido.", "explicacao": "Ex.: charge, infográfico, propaganda e meme."}, {"id": 2000003518, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é antítese?", "verso": "Aproximação de ideias opostas: \"Nasce o sol e não dura mais que um dia\".", "explicacao": "Diferente do paradoxo, em que as ideias opostas se fundem num absurdo aparente."}, {"id": 2000003519, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é gradação?", "verso": "Sequência de palavras ou ideias em ordem crescente ou decrescente de intensidade.", "explicacao": "Ex.: \"Chegou, olhou, venceu\"."}, {"id": 2000003520, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é onomatopeia?", "verso": "Palavra que imita um som: \"tic-tac\", \"pow\", \"miau\".", "explicacao": "Comum em HQs."}, {"id": 2000003521, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é assonância?", "verso": "Repetição de sons vocálicos para criar efeito sonoro.", "explicacao": "A aliteração repete consoantes."}, {"id": 2000003522, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é catacrese?", "verso": "Metáfora já incorporada à língua por falta de termo próprio: \"pé da mesa\", \"braço da cadeira\".", "explicacao": "Deixa de ser percebida como figura."}, {"id": 2000003523, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é elipse?", "verso": "Omissão de um termo que se subentende pelo contexto: \"Na sala, apenas três alunos\" (omite \"havia\").", "explicacao": "A zeugma é a omissão de termo já mencionado."}, {"id": 2000003524, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é anáfora (figura de linguagem)?", "verso": "Repetição da mesma palavra ou expressão no início de versos ou frases.", "explicacao": "Recurso de ênfase e ritmo."}, {"id": 2000003525, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é pleonasmo literário?", "verso": "Redundância intencional para dar ênfase: \"Vi com estes olhos\".", "explicacao": "Diferente do pleonasmo vicioso (\"subir para cima\")."}, {"id": 2000003526, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que são operadores argumentativos?", "verso": "Palavras que orientam a argumentação, como \"até\", \"mesmo\", \"apenas\", \"inclusive\" e \"ainda\".", "explicacao": "Indicam o peso e a direção dos argumentos."}, {"id": 2000003527, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é pressuposto?", "verso": "Informação que fica implícita, mas é garantida por uma palavra do texto: \"Ele parou de fumar\" pressupõe que fumava.", "explicacao": "Diferente do subentendido, que depende da interpretação do leitor."}, {"id": 2000003528, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é subentendido?", "verso": "Informação sugerida pelo contexto, que o leitor deduz, mas o autor pode negar.", "explicacao": "Ex.: \"Está frio aqui\" pode sugerir \"feche a janela\"."}, {"id": 2000003529, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é o efeito de sentido da ironia em um texto?", "verso": "Dizer o contrário do que se pensa para criticar ou provocar humor, contando que o leitor perceba a intenção.", "explicacao": "Depende do contexto e do conhecimento compartilhado."}, {"id": 2000003530, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é discurso direto e discurso indireto?", "verso": "Direto: a fala do personagem é reproduzida literalmente, com travessão ou aspas. Indireto: o narrador conta com suas palavras o que o personagem disse.", "explicacao": "No indireto livre, a fala se mistura à do narrador."}, {"id": 2000003531, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é discurso indireto livre?", "verso": "Mistura da voz do narrador com a do personagem, sem marcas de fala, revelando pensamentos.", "explicacao": "Muito usado por Graciliano Ramos e Clarice Lispector."}, {"id": 2000003532, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pares", "frente": "Qual a diferença entre narrador observador e narrador personagem?", "verso": "Observador: em 3ª pessoa, conta a história de fora. Personagem: em 1ª pessoa, participa da história.", "explicacao": "O narrador onisciente sabe tudo, inclusive pensamentos."}, {"id": 2000003533, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "O que avalia a competência 3 da redação do Enem?", "verso": "Selecionar, relacionar, organizar e interpretar informações, fatos e argumentos em defesa de um ponto de vista.", "explicacao": "É a qualidade do projeto de texto."}, {"id": 2000003534, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "Quais os elementos de uma proposta de intervenção completa no Enem?", "verso": "Agente, ação, meio ou modo, efeito (finalidade) e detalhamento.", "explicacao": "Deve respeitar os direitos humanos."}, {"id": 2000003535, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "Qual a nota máxima da redação do Enem?", "verso": "1.000 pontos, sendo até 200 por competência.", "explicacao": "São 5 competências."}, {"id": 2000003536, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Memórias Póstumas de Brás Cubas\" e por que a obra é marcante?", "verso": "Machado de Assis (1881). É narrada por um \"defunto autor\" e inaugura o Realismo no Brasil.", "explicacao": "Ironia, pessimismo e diálogo com o leitor."}, {"id": 2000003537, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"O Cortiço\" e a que escola pertence?", "verso": "Aluísio Azevedo (1890), obra do Naturalismo.", "explicacao": "Mostra o meio e a raça determinando o comportamento das personagens."}, {"id": 2000003538, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Vidas Secas\"?", "verso": "Graciliano Ramos (1938), romance regionalista da geração de 30.", "explicacao": "Retrata a família de retirantes Fabiano, sinha Vitória e a cachorra Baleia."}, {"id": 2000003539, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Macunaíma\"?", "verso": "Mário de Andrade (1928), na 1ª fase do Modernismo.", "explicacao": "O \"herói sem nenhum caráter\" mistura lendas e culturas do Brasil."}, {"id": 2000003540, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Os Sertões\"?", "verso": "Euclides da Cunha (1902), sobre a Guerra de Canudos.", "explicacao": "Obra do Pré-Modernismo, entre jornalismo, ciência e literatura."}, {"id": 2000003541, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem criou o personagem Jeca Tatu?", "verso": "Monteiro Lobato, escritor do Pré-Modernismo.", "explicacao": "Retrato crítico do caboclo do interior paulista."}, {"id": 2000003542, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Triste Fim de Policarpo Quaresma\"?", "verso": "Lima Barreto (1915), no Pré-Modernismo.", "explicacao": "Critica o nacionalismo ingênuo e a República."}, {"id": 2000003543, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"O Guarani\" e \"Iracema\"?", "verso": "José de Alencar, no Romantismo indianista.", "explicacao": "\"Iracema\" é anagrama de \"América\"."}, {"id": 2000003544, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Castro Alves?", "verso": "O \"poeta dos escravos\", da 3ª geração romântica (condoreira), autor de \"O Navio Negreiro\".", "explicacao": "Poesia social e abolicionista."}, {"id": 2000003545, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Álvares de Azevedo?", "verso": "Poeta da 2ª geração romântica (ultrarromântica ou \"mal do século\"), autor de \"Lira dos Vinte Anos\".", "explicacao": "Temas: morte, tédio, amor idealizado."}, {"id": 2000003546, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Gonçalves Dias?", "verso": "Poeta da 1ª geração romântica, autor de \"Canção do Exílio\" e \"I-Juca Pirama\".", "explicacao": "Nacionalismo e indianismo."}, {"id": 2000003547, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Cruz e Sousa?", "verso": "O principal poeta do Simbolismo brasileiro, autor de \"Broquéis\" (1893).", "explicacao": "Musicalidade, espiritualidade e obsessão pela cor branca."}, {"id": 2000003548, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Olavo Bilac?", "verso": "O principal poeta do Parnasianismo, o \"príncipe dos poetas\".", "explicacao": "Culto à forma, ao soneto e à rima rica."}, {"id": 2000003549, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem foi Tomás Antônio Gonzaga?", "verso": "Poeta árcade, autor de \"Marília de Dirceu\", envolvido na Inconfidência Mineira.", "explicacao": "Pastoralismo e bucolismo."}, {"id": 2000003550, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"O Auto da Compadecida\"?", "verso": "Ariano Suassuna (1955).", "explicacao": "Mistura cultura popular nordestina, religiosidade e humor."}, {"id": 2000003551, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Quarto de Despejo\"?", "verso": "Carolina Maria de Jesus (1960), diário de uma moradora da favela do Canindé, em São Paulo.", "explicacao": "Marco da literatura de testemunho e da literatura negra."}, {"id": 2000003552, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"Grande Sertão: Veredas\"?", "verso": "Guimarães Rosa (1956).", "explicacao": "Narrado por Riobaldo, com linguagem inventiva e neologismos."}, {"id": 2000003553, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem escreveu \"A Hora da Estrela\"?", "verso": "Clarice Lispector (1977).", "explicacao": "Narra a vida de Macabéa, nordestina pobre no Rio de Janeiro."}, {"id": 2000003554, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Qual a principal característica do Barroco?", "verso": "O conflito entre fé e razão, espírito e matéria, expresso em antíteses e paradoxos.", "explicacao": "Cultismo (jogo de palavras) e conceptismo (jogo de ideias)."}, {"id": 2000003555, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que é a literatura de informação do Quinhentismo?", "verso": "Textos dos viajantes e cronistas sobre a nova terra, como a Carta de Pero Vaz de Caminha (1500).", "explicacao": "Ao lado da literatura de catequese, dos jesuítas."}, {"id": 2000003556, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem é Conceição Evaristo e o que é \"escrevivência\"?", "verso": "Escritora mineira, autora de \"Ponciá Vicêncio\". Escrevivência é a escrita a partir das vivências, sobretudo de mulheres negras.", "explicacao": "Conceito muito presente em provas recentes."}, {"id": 2000003557, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que foi o Expressionismo?", "verso": "Movimento artístico do início do século XX que deforma as formas e usa cores intensas para expressar emoções e angústias.", "explicacao": "Ex.: \"O Grito\", de Edvard Munch."}, {"id": 2000003558, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que foi o Dadaísmo?", "verso": "Movimento de vanguarda surgido na Primeira Guerra que rejeitava a lógica e a arte tradicional, com humor e provocação.", "explicacao": "Ex.: \"A Fonte\", de Marcel Duchamp (um mictório)."}, {"id": 2000003559, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que foi o Futurismo?", "verso": "Vanguarda italiana que exaltava a velocidade, as máquinas e a vida moderna.", "explicacao": "Manifesto de Marinetti (1909)."}, {"id": 2000003560, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "Quem foi Candido Portinari?", "verso": "Pintor modernista brasileiro, autor de \"Os Retirantes\" e dos painéis \"Guerra e Paz\" da ONU.", "explicacao": "Temas sociais do povo brasileiro."}, {"id": 2000003561, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "Quem foi Anita Malfatti e por que sua exposição de 1917 foi importante?", "verso": "Pintora cuja exposição com influências expressionistas causou polêmica (crítica de Monteiro Lobato) e antecipou o Modernismo.", "explicacao": "Considerada estopim da Semana de 1922."}, {"id": 2000003562, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que é arte urbana (street art)?", "verso": "Expressões artísticas em espaços públicos, como grafite, murais e lambe-lambes.", "explicacao": "Diferente da pichação, embora o limite seja debatido."}, {"id": 2000003563, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que é performance na arte contemporânea?", "verso": "Obra em que o próprio corpo do artista, a ação e o tempo fazem parte da arte, muitas vezes com participação do público.", "explicacao": "Ex.: trabalhos de Marina Abramović."}, {"id": 2000003564, "trilha": "enem", "materia": "ling", "assunto": "Educação física", "tipo": "pergunta", "frente": "O que diferencia esporte de jogo, na educação física escolar?", "verso": "O esporte tem regras institucionalizadas e competição oficial; o jogo tem regras mais flexíveis, combinadas pelos participantes.", "explicacao": "Tema recorrente no Enem."}, {"id": 2000003565, "trilha": "enem", "materia": "ling", "assunto": "Educação física", "tipo": "pergunta", "frente": "O que são práticas corporais de aventura?", "verso": "Atividades com risco controlado em ambientes urbanos ou na natureza, como parkour, skate, trilhas e escalada.", "explicacao": "Previstas na BNCC."}, {"id": 2000003566, "trilha": "enem", "materia": "ling", "assunto": "Educação física", "tipo": "pergunta", "frente": "O que diz o Enem sobre padrões de beleza e corpo?", "verso": "Costuma criticar a imposição de padrões pela mídia e valorizar a diversidade corporal e a saúde.", "explicacao": "Ligado a temas como distúrbios alimentares e consumo."}, {"id": 2000003567, "trilha": "enem", "materia": "ling", "assunto": "Inglês", "tipo": "pergunta", "frente": "O que significam \"however\" e \"therefore\" em inglês?", "verso": "\"However\": no entanto (oposição). \"Therefore\": portanto (conclusão).", "explicacao": "Conectivos ajudam a entender a argumentação do texto."}, {"id": 2000003568, "trilha": "enem", "materia": "ling", "assunto": "Inglês", "tipo": "pergunta", "frente": "O que significam os falsos cognatos \"actually\" e \"pretend\"?", "verso": "\"Actually\": na verdade. \"Pretend\": fingir.", "explicacao": "Não significam \"atualmente\" nem \"pretender\"."}, {"id": 2000003569, "trilha": "enem", "materia": "ling", "assunto": "Espanhol", "tipo": "pergunta", "frente": "Em espanhol, o que significam \"embarazada\" e \"borrar\"?", "verso": "\"Embarazada\": grávida. \"Borrar\": apagar.", "explicacao": "Falsos amigos (heterossemânticos)."}, {"id": 2000003570, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é a maiêutica socrática?", "verso": "Método de \"parto das ideias\": por perguntas, Sócrates levava o interlocutor a descobrir a verdade por si mesmo.", "explicacao": "Precedida pela ironia, que mostrava a ignorância."}, {"id": 2000003571, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é o mundo das ideias para Platão?", "verso": "Realidade perfeita, eterna e imutável, da qual o mundo sensível é apenas cópia imperfeita.", "explicacao": "Conhecer é recordar as ideias (reminiscência)."}, {"id": 2000003572, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "Qual a tripartição da alma em Platão?", "verso": "Racional (cabeça), irascível (coração) e concupiscível (ventre).", "explicacao": "Corresponde às classes da cidade ideal: governantes-filósofos, guardiões e produtores."}, {"id": 2000003573, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é a justa medida (mesotes) em Aristóteles?", "verso": "A virtude como meio-termo entre dois vícios, um por excesso e outro por falta.", "explicacao": "Ex.: coragem entre a covardia e a temeridade."}, {"id": 2000003574, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é a eudaimonia para Aristóteles?", "verso": "A felicidade, entendida como finalidade última da vida humana, alcançada pela prática das virtudes.", "explicacao": "Ética teleológica (voltada a um fim)."}, {"id": 2000003575, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "Quais as quatro causas de Aristóteles?", "verso": "Material (de que é feito), formal (o que é), eficiente (quem fez) e final (para que serve).", "explicacao": "Ex.: uma estátua: bronze, forma, escultor, homenagem."}, {"id": 2000003576, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é a arché para os pré-socráticos?", "verso": "O princípio fundamental de todas as coisas.", "explicacao": "Tales: água; Anaxímenes: ar; Heráclito: fogo; Pitágoras: números."}, {"id": 2000003577, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que defendiam os céticos?", "verso": "Que não é possível alcançar certezas, e por isso se deve suspender o juízo (epoché).", "explicacao": "Pirro de Élis é o principal nome."}, {"id": 2000003578, "trilha": "enem", "materia": "fil", "assunto": "Filosofia medieval", "tipo": "pergunta", "frente": "O que é a escolástica?", "verso": "Filosofia medieval que buscava conciliar a fé cristã com a razão, especialmente com Aristóteles.", "explicacao": "Principal nome: São Tomás de Aquino."}, {"id": 2000003579, "trilha": "enem", "materia": "fil", "assunto": "Filosofia medieval", "tipo": "pergunta", "frente": "O que defendia Santo Agostinho sobre o mal?", "verso": "Que o mal não é uma substância, mas a ausência do bem, ligada ao mau uso do livre-arbítrio.", "explicacao": "Influência de Platão (neoplatonismo)."}, {"id": 2000003580, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é a dúvida metódica de Descartes?", "verso": "Duvidar de tudo o que não for absolutamente certo, para encontrar uma verdade indubitável: \"penso, logo existo\".", "explicacao": "Base do racionalismo moderno."}, {"id": 2000003581, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é a tábula rasa de John Locke?", "verso": "A ideia de que a mente nasce vazia e todo conhecimento vem da experiência.", "explicacao": "Empirismo."}, {"id": 2000003582, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que defendia David Hume sobre a causalidade?", "verso": "Que a relação de causa e efeito vem do hábito de ver fatos se sucederem, e não de uma necessidade comprovada pela razão.", "explicacao": "Empirismo cético."}, {"id": 2000003583, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é o estado de natureza para Hobbes?", "verso": "Uma \"guerra de todos contra todos\", em que o homem é lobo do homem, por isso os indivíduos criam o Estado forte (Leviatã).", "explicacao": "Contratualismo absolutista."}, {"id": 2000003584, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é o estado de natureza para Rousseau?", "verso": "Um estado em que o homem é bom e livre; a sociedade e a propriedade privada o corrompem.", "explicacao": "Defende a vontade geral e a soberania popular."}, {"id": 2000003585, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "Quais os direitos naturais para Locke?", "verso": "Vida, liberdade e propriedade. O governo existe para protegê-los, e o povo pode resistir ao governo tirano.", "explicacao": "Base do liberalismo político."}, {"id": 2000003586, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é a revolução copernicana de Kant?", "verso": "A ideia de que o conhecimento depende das estruturas do sujeito: não é o sujeito que se adapta ao objeto, mas o objeto às formas do sujeito.", "explicacao": "Síntese entre racionalismo e empirismo."}, {"id": 2000003587, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que diz o imperativo categórico de Kant em sua fórmula da humanidade?", "verso": "Agir de modo a tratar a humanidade, em si e nos outros, sempre como fim e nunca apenas como meio.", "explicacao": "Ética do dever (deontológica)."}, {"id": 2000003588, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é a dialética de Hegel?", "verso": "Movimento do pensamento e da história em tese, antítese e síntese.", "explicacao": "Marx a transformou em materialismo dialético."}, {"id": 2000003589, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é o materialismo histórico de Marx?", "verso": "A ideia de que a base econômica (modo de produção) determina a organização da sociedade, e a história é movida pela luta de classes.", "explicacao": "Infraestrutura e superestrutura."}, {"id": 2000003590, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a ideologia para Marx?", "verso": "Conjunto de ideias da classe dominante que oculta a exploração e apresenta a realidade como natural.", "explicacao": "Serve para manter a dominação."}, {"id": 2000003591, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é o \"super-homem\" (além-do-homem) de Nietzsche?", "verso": "O ser humano que supera os valores tradicionais e cria os próprios valores, afirmando a vida.", "explicacao": "Ligado à vontade de potência."}, {"id": 2000003592, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a angústia para Sartre?", "verso": "O sentimento que surge da consciência de que somos totalmente livres e responsáveis por nossas escolhas.", "explicacao": "\"O homem está condenado a ser livre\"."}, {"id": 2000003593, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a razão instrumental para a Escola de Frankfurt?", "verso": "A razão usada só como meio para dominar a natureza e as pessoas, sem refletir sobre os fins.", "explicacao": "Crítica de Adorno e Horkheimer."}, {"id": 2000003594, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é o poder disciplinar em Foucault?", "verso": "Poder que controla os corpos por vigilância, normas e exames, em instituições como prisões, escolas, quartéis e hospitais.", "explicacao": "O panóptico é seu símbolo."}, {"id": 2000003595, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é o panóptico?", "verso": "Modelo de prisão de Jeremy Bentham em que um vigia central pode observar todos sem ser visto, fazendo os presos se vigiarem.", "explicacao": "Usado por Foucault como metáfora da sociedade disciplinar."}, {"id": 2000003596, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a ação comunicativa para Habermas?", "verso": "Ação orientada ao entendimento por meio do diálogo racional, em que vence o melhor argumento.", "explicacao": "Base da democracia deliberativa."}, {"id": 2000003597, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a teoria da justiça de John Rawls?", "verso": "Princípios de justiça escolhidos sob o \"véu da ignorância\", em que ninguém sabe sua posição social, levando a proteger os mais desfavorecidos.", "explicacao": "Princípio da diferença."}, {"id": 2000003598, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a \"condição humana\" para Hannah Arendt?", "verso": "As atividades humanas fundamentais: trabalho (necessidade), obra (fabricação) e ação (política).", "explicacao": "A ação é a mais propriamente humana."}, {"id": 2000003599, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é ética deontológica?", "verso": "Ética baseada no dever e em regras, independentemente das consequências.", "explicacao": "Kant é o principal representante."}, {"id": 2000003600, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é ética consequencialista?", "verso": "Ética que julga as ações pelas consequências; a mais conhecida é o utilitarismo.", "explicacao": "Bentham e Stuart Mill."}, {"id": 2000003601, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é bioética?", "verso": "Área da ética que estuda questões ligadas à vida e à saúde, como aborto, eutanásia, clonagem e pesquisas com seres humanos.", "explicacao": "Princípios: autonomia, beneficência, não maleficência e justiça."}, {"id": 2000003602, "trilha": "enem", "materia": "fil", "assunto": "Lógica", "tipo": "pergunta", "frente": "O que é uma falácia?", "verso": "Raciocínio que parece válido, mas é incorreto.", "explicacao": "Ex.: ataque à pessoa (ad hominem), apelo à autoridade, falso dilema."}, {"id": 2000003603, "trilha": "enem", "materia": "fil", "assunto": "Lógica", "tipo": "pergunta", "frente": "O que é a falácia ad hominem?", "verso": "Atacar a pessoa em vez de refutar o argumento dela.", "explicacao": "Muito comum em debates."}, {"id": 2000003604, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é anomia para Durkheim?", "verso": "Situação de enfraquecimento das normas sociais, que deixa os indivíduos sem referências.", "explicacao": "Ele a relacionou a certos tipos de suicídio."}, {"id": 2000003605, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é o tipo ideal de Max Weber?", "verso": "Modelo teórico construído pelo pesquisador, com traços essenciais de um fenômeno, para compará-lo com a realidade.", "explicacao": "Ex.: tipos de dominação."}, {"id": 2000003606, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é a \"ética protestante\" para Weber?", "verso": "Conjunto de valores (trabalho, disciplina, poupança) que favoreceu o desenvolvimento do capitalismo.", "explicacao": "Obra \"A ética protestante e o espírito do capitalismo\" (1905)."}, {"id": 2000003607, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é a burocracia para Weber?", "verso": "Forma de organização baseada em regras impessoais, hierarquia e competência técnica, típica da dominação racional-legal.", "explicacao": "Pode gerar a \"jaula de ferro\"."}, {"id": 2000003608, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é capital cultural para Pierre Bourdieu?", "verso": "Conhecimentos, gostos e diplomas herdados ou adquiridos, que ajudam a reproduzir as desigualdades sociais, inclusive na escola.", "explicacao": "Junto com o capital econômico e o social."}, {"id": 2000003609, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é habitus para Bourdieu?", "verso": "Disposições incorporadas pela pessoa ao longo da vida, que orientam gostos e comportamentos conforme sua posição social.", "explicacao": "Explica a reprodução social."}, {"id": 2000003610, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é relativismo cultural?", "verso": "A ideia de que cada cultura deve ser compreendida a partir de seus próprios valores, sem hierarquizá-las.", "explicacao": "Oposto do etnocentrismo."}, {"id": 2000003611, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é aculturação?", "verso": "Processo de mudança cultural resultante do contato contínuo entre culturas diferentes.", "explicacao": "Pode ocorrer com imposição de uma cultura sobre outra."}, {"id": 2000003612, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é mobilidade social?", "verso": "Mudança de posição de uma pessoa ou grupo na estrutura social, para cima (ascendente) ou para baixo (descendente).", "explicacao": "É rara em sociedades de castas."}, {"id": 2000003613, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é o \"capital social\" em sociologia?", "verso": "A rede de relações e contatos de uma pessoa, que pode trazer vantagens.", "explicacao": "Conceito usado por Bourdieu e Putnam."}, {"id": 2000003614, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é sociedade de risco (Ulrich Beck)?", "verso": "Sociedade em que os próprios avanços técnicos produzem riscos globais, como desastres ambientais e nucleares.", "explicacao": "Riscos que atingem todos, ricos e pobres."}, {"id": 2000003615, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é a \"sociedade em rede\" de Manuel Castells?", "verso": "Sociedade organizada em torno de redes de informação e comunicação digitais.", "explicacao": "Era da informação."}, {"id": 2000003616, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "O que é o Estado de bem-estar social?", "verso": "Modelo em que o Estado garante direitos sociais, como saúde, educação e previdência, e intervém na economia.", "explicacao": "Fortaleceu-se após a Segunda Guerra."}, {"id": 2000003617, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "O que é o neoliberalismo?", "verso": "Política que defende Estado mínimo na economia, privatizações, abertura comercial e redução de gastos sociais.", "explicacao": "Ganhou força nos anos 1980 (Thatcher e Reagan)."}, {"id": 2000003618, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "O que é totalitarismo para Hannah Arendt?", "verso": "Regime que busca dominar todos os aspectos da vida, com partido único, ideologia oficial, terror e propaganda.", "explicacao": "Ex.: nazismo e stalinismo."}, {"id": 2000003619, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "O que é o poder simbólico (Bourdieu)?", "verso": "Poder invisível que se exerce pela imposição de significados e valores, aceitos como naturais pelos dominados.", "explicacao": "Ligado à violência simbólica."}, {"id": 2000003620, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Um produto de R$ 200 teve desconto de 30%. Qual o preço final?", "verso": "R$ 140.", "explicacao": "200 × 0,7 = 140."}, {"id": 2000003621, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Um salário de R$ 2.500 teve aumento de 8%. Qual o novo salário?", "verso": "R$ 2.700.", "explicacao": "2.500 × 1,08 = 2.700."}, {"id": 2000003622, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Após um desconto de 20%, um produto passou a custar R$ 64. Qual era o preço original?", "verso": "R$ 80.", "explicacao": "64 ÷ 0,8 = 80. Erro comum: somar 20% a 64."}, {"id": 2000003623, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Qual o desconto único equivalente a dois descontos sucessivos de 20%?", "verso": "36%.", "explicacao": "0,8 × 0,8 = 0,64, ou seja, paga-se 64%."}, {"id": 2000003624, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "O que significa um aumento de 100%?", "verso": "Que o valor dobrou.", "explicacao": "Aumento de 200% significa que triplicou."}, {"id": 2000003625, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "O que são pontos percentuais?", "verso": "A diferença simples entre duas porcentagens: de 10% para 15% há aumento de 5 pontos percentuais (e de 50% em termos relativos).", "explicacao": "Pegadinha comum em gráficos de taxas."}, {"id": 2000003626, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pergunta", "frente": "Qual a fórmula do montante nos juros compostos?", "verso": "M = C × (1 + i)ⁿ.", "explicacao": "C: capital; i: taxa na forma decimal; n: número de períodos."}, {"id": 2000003627, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pergunta", "frente": "Qual a fórmula dos juros simples?", "verso": "J = C × i × t.", "explicacao": "O montante é M = C + J."}, {"id": 2000003628, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pergunta", "frente": "Uma compra de R$ 1.200 pode ser paga à vista com 10% de desconto ou em 3 vezes de R$ 400. Qual a diferença?", "verso": "R$ 120: à vista custa R$ 1.080.", "explicacao": "1.200 × 0,9 = 1.080."}, {"id": 2000003629, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Uma receita usa 2 xícaras de farinha para 3 ovos. Quantas xícaras são necessárias para 12 ovos?", "verso": "8 xícaras.", "explicacao": "12 ÷ 3 = 4; 4 × 2 = 8."}, {"id": 2000003630, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Em um mapa de escala 1:200.000, quantos km correspondem a 3 cm?", "verso": "6 km.", "explicacao": "3 × 200.000 = 600.000 cm = 6 km."}, {"id": 2000003631, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Em uma planta na escala 1:100, um cômodo mede 4 cm por 5 cm. Qual a área real?", "verso": "20 m².", "explicacao": "4 m × 5 m = 20 m². A área é proporcional ao quadrado da escala."}, {"id": 2000003632, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Como dividir R$ 900 em partes proporcionais a 2 e 3?", "verso": "R$ 360 e R$ 540.", "explicacao": "900 ÷ (2 + 3) = 180; 2 × 180 e 3 × 180."}, {"id": 2000003633, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "O que é densidade demográfica e como se calcula?", "verso": "Número de habitantes por área: população ÷ área (hab/km²).", "explicacao": "Ex.: 50.000 habitantes em 200 km² = 250 hab/km²."}, {"id": 2000003634, "trilha": "enem", "materia": "mat", "assunto": "Regra de três", "tipo": "pergunta", "frente": "Uma torneira enche um tanque em 6 horas. Três torneiras iguais enchem o mesmo tanque em quanto tempo?", "verso": "2 horas.", "explicacao": "Grandezas inversamente proporcionais: 6 ÷ 3."}, {"id": 2000003635, "trilha": "enem", "materia": "mat", "assunto": "Regra de três", "tipo": "pergunta", "frente": "Um carro faz 12 km por litro. Quantos litros gasta em 300 km?", "verso": "25 litros.", "explicacao": "300 ÷ 12 = 25."}, {"id": 2000003636, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Quantos centímetros cúbicos há em 1 litro?", "verso": "1.000 cm³.", "explicacao": "1 L = 1 dm³ = 1.000 cm³ = 1.000 mL."}, {"id": 2000003637, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Quantos minutos há em 2,5 horas?", "verso": "150 minutos.", "explicacao": "0,5 h = 30 min. Erro comum: ler 2,5 h como 2 h 50 min."}, {"id": 2000003638, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Quantos metros quadrados há em 1 km²?", "verso": "1.000.000 m².", "explicacao": "1 km = 1.000 m; 1.000 × 1.000."}, {"id": 2000003639, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Como converter m/s em km/h?", "verso": "Multiplica-se por 3,6.", "explicacao": "Ex.: 20 m/s = 72 km/h."}, {"id": 2000003640, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Qual a média de 4, 7, 7, 10 e 12?", "verso": "8.", "explicacao": "Soma 40 ÷ 5."}, {"id": 2000003641, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Qual a moda de 2, 3, 3, 5, 5, 5, 8?", "verso": "5.", "explicacao": "Valor que mais aparece."}, {"id": 2000003642, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Qual a mediana de 7, 1, 9, 4, 5?", "verso": "5.", "explicacao": "Ordenando: 1, 4, 5, 7, 9."}, {"id": 2000003643, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "O que é amplitude de um conjunto de dados?", "verso": "A diferença entre o maior e o menor valor.", "explicacao": "Medida simples de dispersão."}, {"id": 2000003644, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Por que a mediana pode representar melhor um conjunto com valores extremos que a média?", "verso": "Porque não é afetada por valores muito altos ou muito baixos (outliers).", "explicacao": "Ex.: salários de uma empresa com um diretor muito bem pago."}, {"id": 2000003645, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Como se calcula a variância populacional?", "verso": "Média dos quadrados dos desvios em relação à média.", "explicacao": "O desvio padrão é a raiz quadrada da variância."}, {"id": 2000003646, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "O que é frequência relativa?", "verso": "A frequência de um valor dividida pelo total de observações, geralmente em porcentagem.", "explicacao": "Ex.: 12 alunos de 40 = 30%."}, {"id": 2000003647, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Qual gráfico é mais indicado para mostrar a evolução de uma grandeza no tempo?", "verso": "O gráfico de linhas.", "explicacao": "O de setores (pizza) mostra partes de um todo."}, {"id": 2000003648, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "O que é um histograma?", "verso": "Gráfico de barras justapostas que mostra a distribuição de frequências de dados agrupados em intervalos.", "explicacao": "As barras encostam porque os intervalos são contínuos."}, {"id": 2000003649, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Uma urna tem 3 bolas azuis e 7 vermelhas. Qual a probabilidade de tirar uma azul?", "verso": "3/10 (30%).", "explicacao": "Casos favoráveis ÷ casos possíveis."}, {"id": 2000003650, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Retirando 2 bolas sem reposição de uma urna com 3 azuis e 7 vermelhas, qual a probabilidade de as duas serem azuis?", "verso": "1/15.", "explicacao": "3/10 × 2/9 = 6/90 = 1/15."}, {"id": 2000003651, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de tirar dois números 6 lançando dois dados?", "verso": "1/36.", "explicacao": "1/6 × 1/6."}, {"id": 2000003652, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "O que é probabilidade condicional?", "verso": "A probabilidade de A ocorrer sabendo que B ocorreu: P(A|B) = P(A ∩ B) ÷ P(B).", "explicacao": "O espaço amostral fica reduzido a B."}, {"id": 2000003653, "trilha": "enem", "materia": "mat", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos anagramas tem a palavra CASA?", "verso": "12.", "explicacao": "4! ÷ 2! = 24 ÷ 2 (o A se repete)."}, {"id": 2000003654, "trilha": "enem", "materia": "mat", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos jogos há em um campeonato de turno único com 10 times?", "verso": "45 jogos.", "explicacao": "C(10,2) = 10 × 9 ÷ 2."}, {"id": 2000003655, "trilha": "enem", "materia": "mat", "assunto": "Contagem", "tipo": "pergunta", "frente": "De quantas formas é possível escolher presidente e vice entre 8 candidatos?", "verso": "56.", "explicacao": "Arranjo: 8 × 7 (a ordem importa)."}, {"id": 2000003656, "trilha": "enem", "materia": "mat", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos números de 3 algarismos distintos podem ser formados com 1, 2, 3, 4 e 5?", "verso": "60.", "explicacao": "5 × 4 × 3."}, {"id": 2000003657, "trilha": "enem", "materia": "mat", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos apertos de mão ocorrem quando 6 pessoas se cumprimentam uma única vez?", "verso": "15.", "explicacao": "C(6,2) = 6 × 5 ÷ 2."}, {"id": 2000003658, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "O que é o zero (raiz) de uma função?", "verso": "O valor de x que faz f(x) = 0, onde o gráfico corta o eixo x.", "explicacao": "Na função afim f(x) = ax + b, a raiz é x = −b ÷ a."}, {"id": 2000003659, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Uma corrida de táxi custa R$ 5 fixos mais R$ 3 por km. Qual a função do preço?", "verso": "P(x) = 3x + 5, em que x são os km rodados.", "explicacao": "Função afim: 5 é a parte fixa e 3 é a taxa de variação."}, {"id": 2000003660, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Qual o y do vértice da parábola y = ax² + bx + c?", "verso": "yv = −Δ ÷ 4a.", "explicacao": "O vértice é o ponto de máximo (a < 0) ou mínimo (a > 0)."}, {"id": 2000003661, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quais as raízes de x² − 5x + 6 = 0?", "verso": "2 e 3.", "explicacao": "Soma = 5 e produto = 6 (relações de Girard)."}, {"id": 2000003662, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quais as relações de soma e produto das raízes de ax² + bx + c = 0?", "verso": "Soma = −b ÷ a e produto = c ÷ a.", "explicacao": "Úteis para achar raízes rapidamente."}, {"id": 2000003663, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quando a função exponencial f(x) = aˣ é crescente?", "verso": "Quando a base a é maior que 1. Se 0 < a < 1, é decrescente.", "explicacao": "Ex.: crescimento de bactérias e juros compostos."}, {"id": 2000003664, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Uma população de bactérias dobra a cada hora. Começando com 100, quantas haverá após 5 horas?", "verso": "3.200.", "explicacao": "100 × 2⁵ = 100 × 32."}, {"id": 2000003665, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Uma substância tem meia-vida de 10 anos. De 80 g, quanto resta após 30 anos?", "verso": "10 g.", "explicacao": "80 → 40 → 20 → 10 (três meias-vidas)."}, {"id": 2000003666, "trilha": "enem", "materia": "mat", "assunto": "Logaritmos", "tipo": "pergunta", "frente": "Qual a propriedade do logaritmo de uma potência?", "verso": "log_b(aⁿ) = n × log_b(a).", "explicacao": "Útil para resolver equações exponenciais."}, {"id": 2000003667, "trilha": "enem", "materia": "mat", "assunto": "Logaritmos", "tipo": "pergunta", "frente": "Qual a propriedade do logaritmo de um quociente?", "verso": "log_b(a ÷ c) = log_b(a) − log_b(c).", "explicacao": "O do produto vira soma."}, {"id": 2000003668, "trilha": "enem", "materia": "mat", "assunto": "Logaritmos", "tipo": "pergunta", "frente": "Onde aparece a escala logarítmica no cotidiano?", "verso": "Na escala Richter de terremotos, no pH e no nível sonoro em decibéis.", "explicacao": "Cada ponto a mais na Richter representa 10 vezes mais amplitude."}, {"id": 2000003669, "trilha": "enem", "materia": "mat", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o 10º termo da PA 3, 7, 11, …?", "verso": "39.", "explicacao": "a10 = 3 + 9 × 4."}, {"id": 2000003670, "trilha": "enem", "materia": "mat", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o 5º termo da PG 2, 6, 18, …?", "verso": "162.", "explicacao": "a5 = 2 × 3⁴ = 162."}, {"id": 2000003671, "trilha": "enem", "materia": "mat", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual a soma dos números de 1 a 100?", "verso": "5.050.", "explicacao": "(1 + 100) × 100 ÷ 2 (soma de Gauss)."}, {"id": 2000003672, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Qual a área de um retângulo de 8 m por 5 m e qual o perímetro?", "verso": "Área: 40 m². Perímetro: 26 m.", "explicacao": "Perímetro = 2 × (8 + 5)."}, {"id": 2000003673, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Qual a área de um círculo de raio 10 cm (use π = 3,14)?", "verso": "314 cm².", "explicacao": "A = π × r²."}, {"id": 2000003674, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Qual a diagonal de um quadrado de lado 5 cm?", "verso": "5√2 cm (cerca de 7,07 cm).", "explicacao": "d = lado × √2 (Pitágoras)."}, {"id": 2000003675, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Qual a altura de um triângulo equilátero de lado 6 cm?", "verso": "3√3 cm (cerca de 5,2 cm).", "explicacao": "h = lado × √3 ÷ 2."}, {"id": 2000003676, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Qual a soma dos ângulos internos de um hexágono?", "verso": "720°.", "explicacao": "S = (n − 2) × 180° = 4 × 180°."}, {"id": 2000003677, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Quanto mede cada ângulo interno de um hexágono regular?", "verso": "120°.", "explicacao": "720° ÷ 6."}, {"id": 2000003678, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Quais polígonos regulares sozinhos cobrem o plano sem deixar buracos?", "verso": "Triângulo equilátero, quadrado e hexágono regular.", "explicacao": "Seus ângulos internos dividem 360° exatamente."}, {"id": 2000003679, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Quais os ternos pitagóricos mais comuns?", "verso": "3, 4, 5; 5, 12, 13; 6, 8, 10; 8, 15, 17.", "explicacao": "Agilizam questões de Pitágoras."}, {"id": 2000003680, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "O que diz o teorema de Tales?", "verso": "Retas paralelas cortadas por transversais determinam segmentos proporcionais.", "explicacao": "Base da semelhança de triângulos."}, {"id": 2000003681, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Em triângulos semelhantes com razão k entre os lados, qual a razão entre as áreas?", "verso": "k².", "explicacao": "Se os lados dobram, a área quadruplica."}, {"id": 2000003682, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Se as dimensões de um cubo dobram, o que acontece com o volume?", "verso": "Fica 8 vezes maior.", "explicacao": "O volume varia com o cubo da razão: 2³ = 8."}, {"id": 2000003683, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Qual o volume de uma caixa de 2 m × 3 m × 1,5 m em litros?", "verso": "9.000 litros.", "explicacao": "2 × 3 × 1,5 = 9 m³ = 9.000 L."}, {"id": 2000003684, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Qual o volume de um cilindro de raio 2 m e altura 5 m (use π = 3)?", "verso": "60 m³.", "explicacao": "V = π × r² × h = 3 × 4 × 5."}, {"id": 2000003685, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Qual a área total de um cubo de aresta 3 cm?", "verso": "54 cm².", "explicacao": "6 faces × 3²."}, {"id": 2000003686, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Quantas faces, vértices e arestas tem um cubo?", "verso": "6 faces, 8 vértices e 12 arestas.", "explicacao": "Euler: V − A + F = 8 − 12 + 6 = 2."}, {"id": 2000003687, "trilha": "enem", "materia": "mat", "assunto": "Trigonometria", "tipo": "pergunta", "frente": "Uma rampa de 10 m forma ângulo de 30° com o chão. Qual a altura alcançada?", "verso": "5 m.", "explicacao": "sen 30° = h ÷ 10, e sen 30° = 1/2."}, {"id": 2000003688, "trilha": "enem", "materia": "mat", "assunto": "Trigonometria", "tipo": "pergunta", "frente": "Quanto valem sen 45° e cos 45°?", "verso": "√2 ÷ 2 (cerca de 0,71) cada um.", "explicacao": "tg 45° = 1."}, {"id": 2000003689, "trilha": "enem", "materia": "mat", "assunto": "Trigonometria", "tipo": "pergunta", "frente": "Qual a relação fundamental da trigonometria?", "verso": "sen² x + cos² x = 1.", "explicacao": "Vale para qualquer ângulo x."}, {"id": 2000003690, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função do retículo endoplasmático rugoso?", "verso": "Síntese de proteínas, graças aos ribossomos aderidos à sua membrana.", "explicacao": "O liso produz lipídios e ajuda a desintoxicar a célula."}, {"id": 2000003691, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função dos lisossomos?", "verso": "Digestão intracelular, com enzimas que quebram substâncias e organelas velhas.", "explicacao": "Ligados à autofagia."}, {"id": 2000003692, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função do vacúolo nas células vegetais?", "verso": "Armazenar água e substâncias e manter a pressão interna (turgor) da célula.", "explicacao": "Na planta murcha, os vacúolos perderam água."}, {"id": 2000003693, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "O que é a membrana plasmática e qual o seu modelo?", "verso": "Envoltório que controla a entrada e a saída de substâncias, formado por bicamada de fosfolipídios com proteínas (modelo do mosaico fluido).", "explicacao": "Permeabilidade seletiva."}, {"id": 2000003694, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função da parede celular nos vegetais?", "verso": "Dar rigidez, proteção e forma à célula; é feita principalmente de celulose.", "explicacao": "Fungos têm parede de quitina."}, {"id": 2000003695, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "O que é o núcleo da célula?", "verso": "Estrutura que guarda o material genético (DNA) e controla as atividades celulares.", "explicacao": "Ausente nas procariontes, que têm nucleoide."}, {"id": 2000003696, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "O que é difusão facilitada?", "verso": "Transporte passivo de substâncias a favor do gradiente de concentração com ajuda de proteínas transportadoras, sem gasto de energia.", "explicacao": "Ex.: entrada de glicose em muitas células."}, {"id": 2000003697, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "O que é a bomba de sódio e potássio?", "verso": "Transporte ativo que leva sódio para fora e potássio para dentro da célula, com gasto de ATP.", "explicacao": "Essencial para o impulso nervoso."}, {"id": 2000003698, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "O que é o ATP?", "verso": "Molécula que armazena e fornece energia para as atividades celulares.", "explicacao": "Produzida principalmente na respiração celular."}, {"id": 2000003699, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pergunta", "frente": "Quais as etapas da respiração celular aeróbica?", "verso": "Glicólise (citoplasma), ciclo de Krebs e cadeia respiratória (mitocôndria).", "explicacao": "Rende muito mais ATP que a fermentação."}, {"id": 2000003700, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pergunta", "frente": "Que tipo de fermentação é usada na produção de pão e de bebidas alcoólicas?", "verso": "A fermentação alcoólica, feita por leveduras, que produz etanol e gás carbônico.", "explicacao": "O CO₂ faz a massa do pão crescer."}, {"id": 2000003701, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pergunta", "frente": "Que tipo de fermentação ocorre no músculo em esforço intenso e na produção de iogurte?", "verso": "A fermentação lática, que produz ácido lático.", "explicacao": "No iogurte, é feita por bactérias."}, {"id": 2000003702, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pergunta", "frente": "Quais as fases da fotossíntese?", "verso": "Fase clara (fotoquímica), que depende de luz e libera O₂, e fase escura (química), em que o CO₂ é fixado e forma glicose.", "explicacao": "O oxigênio liberado vem da quebra da água."}, {"id": 2000003703, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pergunta", "frente": "O que são enzimas?", "verso": "Proteínas que aceleram reações químicas no organismo (catalisadores biológicos).", "explicacao": "São sensíveis a temperatura e pH."}, {"id": 2000003704, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que diz a 2ª lei de Mendel?", "verso": "Genes para características diferentes se separam de forma independente na formação dos gametas.", "explicacao": "Segregação independente."}, {"id": 2000003705, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Qual a proporção fenotípica do cruzamento AaBb × AaBb?", "verso": "9:3:3:1.", "explicacao": "Diibridismo com dominância completa."}, {"id": 2000003706, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Qual a proporção do cruzamento Aa × aa?", "verso": "50% Aa e 50% aa.", "explicacao": "É o cruzamento-teste."}, {"id": 2000003707, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é codominância?", "verso": "Quando os dois alelos se expressam juntos no heterozigoto, como no tipo sanguíneo AB.", "explicacao": "Diferente da dominância incompleta, em que surge um fenótipo intermediário."}, {"id": 2000003708, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é dominância incompleta?", "verso": "O heterozigoto tem fenótipo intermediário, como flores rosas do cruzamento entre vermelhas e brancas.", "explicacao": "Também chamada de herança intermediária."}, {"id": 2000003709, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Quem determina o sexo do bebê na espécie humana?", "verso": "O espermatozoide, que pode levar o cromossomo X (menina) ou Y (menino).", "explicacao": "O óvulo sempre leva X."}, {"id": 2000003710, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é a síndrome de Down?", "verso": "Alteração cromossômica causada por três cromossomos 21 (trissomia do 21).", "explicacao": "É uma aneuploidia."}, {"id": 2000003711, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é o fator Rh?", "verso": "Proteína presente nas hemácias de pessoas Rh+; quem não a tem é Rh−.", "explicacao": "Incompatibilidade Rh na gestação pode causar eritroblastose fetal."}, {"id": 2000003712, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é um gene?", "verso": "Trecho do DNA que contém a informação para produzir uma proteína ou um RNA.", "explicacao": "Conjunto de genes de um organismo: genoma."}, {"id": 2000003713, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é o código genético?", "verso": "A correspondência entre trincas de bases (códons) do RNA e os aminoácidos.", "explicacao": "É praticamente universal entre os seres vivos."}, {"id": 2000003714, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pares", "frente": "Qual a diferença entre transcrição e tradução?", "verso": "Transcrição: produção de RNA a partir do DNA (no núcleo). Tradução: produção da proteína a partir do RNA mensageiro (nos ribossomos).", "explicacao": "Dogma central da biologia."}, {"id": 2000003715, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é uma mutação?", "verso": "Alteração no material genético, que pode ser espontânea ou causada por agentes como radiação e substâncias químicas.", "explicacao": "Fonte de variabilidade para a evolução."}, {"id": 2000003716, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é o teste de DNA para paternidade?", "verso": "Comparação de marcadores genéticos do filho com os do suposto pai: metade dos marcadores vem de cada genitor.", "explicacao": "Também usado na identificação criminal."}, {"id": 2000003717, "trilha": "enem", "materia": "bio", "assunto": "Biotecnologia", "tipo": "pergunta", "frente": "O que é DNA recombinante?", "verso": "DNA formado pela união de trechos de organismos diferentes, usado para produzir, por exemplo, insulina humana em bactérias.", "explicacao": "Base da engenharia genética."}, {"id": 2000003718, "trilha": "enem", "materia": "bio", "assunto": "Biotecnologia", "tipo": "pergunta", "frente": "O que são vacinas de RNA mensageiro?", "verso": "Vacinas que levam às células a instrução (mRNA) para produzir uma proteína do vírus, estimulando a resposta imune.", "explicacao": "Usadas contra a covid-19. O mRNA não altera o DNA."}, {"id": 2000003719, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "O que é seleção artificial?", "verso": "A escolha, pelo ser humano, de indivíduos com características desejadas para a reprodução, como em raças de cães e plantas cultivadas.", "explicacao": "Darwin usou o exemplo para explicar a seleção natural."}, {"id": 2000003720, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "O que é especiação?", "verso": "Formação de novas espécies, geralmente após isolamento geográfico e reprodutivo de populações.", "explicacao": "Especiação alopátrica."}, {"id": 2000003721, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "O que é convergência evolutiva?", "verso": "Quando espécies não aparentadas desenvolvem características parecidas por viverem em ambientes semelhantes.", "explicacao": "Origina órgãos análogos, como as asas de aves e insetos."}, {"id": 2000003722, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "O que são fósseis e qual sua importância?", "verso": "Restos ou vestígios de seres que viveram no passado, preservados em rochas. São evidências da evolução.", "explicacao": "Encontrados principalmente em rochas sedimentares."}, {"id": 2000003723, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que são produtores, consumidores e decompositores?", "verso": "Produtores: fazem fotossíntese (plantas, algas). Consumidores: se alimentam de outros seres. Decompositores: reciclam a matéria orgânica (fungos e bactérias).", "explicacao": "Base das cadeias alimentares."}, {"id": 2000003724, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é pirâmide de energia e por que nunca é invertida?", "verso": "Representa a energia em cada nível trófico; como cerca de 90% se perde a cada nível, a base é sempre maior.", "explicacao": "Pirâmides de número podem ser invertidas."}, {"id": 2000003725, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é competição interespecífica?", "verso": "Disputa por recursos (alimento, espaço) entre espécies diferentes.", "explicacao": "Pode levar à exclusão de uma das espécies."}, {"id": 2000003726, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é predatismo?", "verso": "Relação em que um ser (predador) mata e come outro (presa).", "explicacao": "Controla o tamanho das populações."}, {"id": 2000003727, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é o controle biológico de pragas?", "verso": "Uso de inimigos naturais (predadores, parasitas) para controlar pragas, reduzindo o uso de agrotóxicos.", "explicacao": "Ex.: joaninhas contra pulgões."}, {"id": 2000003728, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é uma espécie endêmica?", "verso": "Espécie que só ocorre naturalmente em uma determinada região.", "explicacao": "Ex.: o mico-leão-dourado na Mata Atlântica."}, {"id": 2000003729, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é o ciclo da água e a evapotranspiração?", "verso": "Circulação da água entre oceanos, atmosfera e continentes. A evapotranspiração soma a evaporação do solo e a transpiração das plantas.", "explicacao": "A floresta devolve muita água à atmosfera."}, {"id": 2000003730, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "Por que o desmatamento da Amazônia afeta as chuvas de outras regiões?", "verso": "Porque a floresta devolve umidade à atmosfera, formando os \"rios voadores\" que levam chuva ao Centro-Oeste e Sudeste.", "explicacao": "Ligação entre biomas e clima."}, {"id": 2000003731, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que são unidades de conservação de proteção integral e de uso sustentável?", "verso": "Proteção integral: só uso indireto (ex.: parques nacionais). Uso sustentável: permite uso direto controlado (ex.: reservas extrativistas).", "explicacao": "Lei do SNUC (Lei 9.985/2000)."}, {"id": 2000003732, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função do sistema linfático?", "verso": "Recolher o excesso de líquido dos tecidos e participar da defesa do organismo.", "explicacao": "Os linfonodos filtram a linfa."}, {"id": 2000003733, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função dos glóbulos brancos (leucócitos)?", "verso": "Defesa do organismo contra agentes estranhos.", "explicacao": "Linfócitos produzem anticorpos."}, {"id": 2000003734, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função das plaquetas?", "verso": "Coagulação do sangue.", "explicacao": "Falta de plaquetas pode causar sangramentos, como na dengue grave."}, {"id": 2000003735, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função do fígado na digestão?", "verso": "Produzir a bile, que emulsiona as gorduras.", "explicacao": "A bile fica armazenada na vesícula biliar."}, {"id": 2000003736, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Onde começa a digestão do amido e qual a enzima?", "verso": "Na boca, pela amilase salivar (ptialina).", "explicacao": "A digestão de proteínas começa no estômago, pela pepsina."}, {"id": 2000003737, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "O que é o diabetes tipo 1 e tipo 2?", "verso": "Tipo 1: o pâncreas não produz insulina. Tipo 2: o corpo não responde bem à insulina (resistência), ligado a hábitos de vida.", "explicacao": "Os dois elevam a glicose no sangue."}, {"id": 2000003738, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função do hormônio antidiurético (ADH)?", "verso": "Aumentar a reabsorção de água nos rins, diminuindo o volume de urina.", "explicacao": "O álcool inibe o ADH, por isso aumenta a urina."}, {"id": 2000003739, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função da adrenalina?", "verso": "Preparar o corpo para situações de estresse (\"luta ou fuga\"): acelera o coração e aumenta a glicose no sangue.", "explicacao": "Produzida pelas glândulas suprarrenais."}, {"id": 2000003740, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "O que é o arco reflexo?", "verso": "Resposta rápida e involuntária a um estímulo, coordenada pela medula espinhal, sem passar pelo cérebro.", "explicacao": "Ex.: tirar a mão de algo quente."}, {"id": 2000003741, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função do neurônio e da sinapse?", "verso": "O neurônio conduz o impulso nervoso; a sinapse é a região de comunicação entre neurônios, com neurotransmissores.", "explicacao": "Ex.: dopamina e serotonina."}, {"id": 2000003742, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a febre amarela e como se previne?", "verso": "Pela picada de mosquitos infectados (Aedes e Haemagogus). A prevenção principal é a vacina.", "explicacao": "Ciclo urbano e silvestre."}, {"id": 2000003743, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a toxoplasmose?", "verso": "Por ingestão de carne crua ou malpassada, alimentos contaminados ou contato com fezes de gatos infectados.", "explicacao": "Perigosa na gestação."}, {"id": 2000003744, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a hepatite A?", "verso": "Pela via fecal-oral, com água e alimentos contaminados.", "explicacao": "As hepatites B e C são transmitidas por sangue e relações sexuais."}, {"id": 2000003745, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a cólera?", "verso": "Por água e alimentos contaminados pela bactéria Vibrio cholerae.", "explicacao": "Prevenção: saneamento e água tratada."}, {"id": 2000003746, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se previne a teníase e a cisticercose?", "verso": "Cozinhando bem carnes de porco e boi, com higiene e saneamento.", "explicacao": "Na cisticercose, a pessoa ingere ovos da tênia."}, {"id": 2000003747, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a leishmaniose?", "verso": "Pela picada do mosquito-palha (flebotomíneo) infectado.", "explicacao": "O cão é reservatório da forma visceral."}, {"id": 2000003748, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite o sarampo e como se previne?", "verso": "Pelo ar (gotículas e aerossóis). A prevenção é a vacina tríplice viral.", "explicacao": "Doença muito contagiosa que voltou com a queda da vacinação."}, {"id": 2000003749, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "O que é a resistência bacteriana e como evitá-la?", "verso": "Seleção de bactérias resistentes pelo uso inadequado de antibióticos. Evita-se usando antibiótico só com receita e pelo tempo indicado.", "explicacao": "Exemplo de seleção natural."}, {"id": 2000003750, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pergunta", "frente": "O que é a polinização?", "verso": "Transporte do pólen até a parte feminina da flor, feito por vento, água, insetos, aves ou morcegos.", "explicacao": "Permite a fecundação nas plantas com flores."}, {"id": 2000003751, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pergunta", "frente": "O que é fototropismo?", "verso": "Crescimento da planta em direção à luz, controlado pelo hormônio auxina.", "explicacao": "O caule tem fototropismo positivo."}, {"id": 2000003752, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pergunta", "frente": "Por que as leguminosas (feijão, soja) enriquecem o solo?", "verso": "Porque suas raízes abrigam bactérias que fixam o nitrogênio do ar.", "explicacao": "Usadas na adubação verde e na rotação de culturas."}, {"id": 2000003753, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "O que são animais ectotérmicos e endotérmicos?", "verso": "Ectotérmicos dependem do ambiente para regular a temperatura (répteis, anfíbios, peixes). Endotérmicos mantêm a temperatura constante (aves e mamíferos).", "explicacao": "Antigos \"sangue frio\" e \"sangue quente\"."}, {"id": 2000003754, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "Quais as características dos artrópodes?", "verso": "Exoesqueleto de quitina, corpo segmentado e patas articuladas.", "explicacao": "Insetos, aracnídeos, crustáceos e miriápodes."}, {"id": 2000003755, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "O que é a ecdise (muda)?", "verso": "Troca periódica do exoesqueleto dos artrópodes, permitindo o crescimento.", "explicacao": "O exoesqueleto não cresce."}, {"id": 2000003756, "trilha": "enem", "materia": "bio", "assunto": "Reprodução", "tipo": "pergunta", "frente": "O que é a pílula anticoncepcional e como age?", "verso": "Hormônios que impedem a ovulação. Não protege contra ISTs.", "explicacao": "Só a camisinha protege contra ISTs."}, {"id": 2000003757, "trilha": "enem", "materia": "bio", "assunto": "Reprodução", "tipo": "pergunta", "frente": "Qual a função da placenta?", "verso": "Trocas de nutrientes, gases e excretas entre a mãe e o feto, além de produzir hormônios.", "explicacao": "Substâncias como álcool e drogas também passam."}, {"id": 2000003758, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pergunta", "frente": "Quais os estados físicos da matéria e suas mudanças?", "verso": "Sólido, líquido e gasoso. Fusão (sólido → líquido), vaporização (líquido → gás), condensação, solidificação e sublimação (sólido → gás).", "explicacao": "A temperatura fica constante durante a mudança de estado da substância pura."}, {"id": 2000003759, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pergunta", "frente": "O que é densidade?", "verso": "A razão entre massa e volume: d = m ÷ V.", "explicacao": "Corpo menos denso que a água flutua."}, {"id": 2000003760, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pergunta", "frente": "Um objeto tem 300 g e 100 cm³. Qual sua densidade? Ele flutua na água?", "verso": "3 g/cm³. Não flutua, pois é mais denso que a água (1 g/cm³).", "explicacao": "d = 300 ÷ 100."}, {"id": 2000003761, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pergunta", "frente": "O que é uma mistura eutética e uma azeotrópica?", "verso": "Eutética: funde a temperatura constante (como liga de solda). Azeotrópica: ferve a temperatura constante (como álcool 96%).", "explicacao": "Comportam-se como substância pura em uma das mudanças."}, {"id": 2000003762, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método separa os componentes da tinta de uma caneta?", "verso": "Cromatografia.", "explicacao": "Os componentes se separam pela diferença de afinidade com o papel e o solvente."}, {"id": 2000003763, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método separa ferro de areia?", "verso": "Separação magnética (imantação).", "explicacao": "O ímã atrai o ferro."}, {"id": 2000003764, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método é usado para separar o sangue em plasma e células?", "verso": "Centrifugação.", "explicacao": "Acelera a separação por diferença de densidade."}, {"id": 2000003765, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Como se separa o petróleo em frações?", "verso": "Por destilação fracionada, pela diferença de pontos de ebulição.", "explicacao": "Origina gás, gasolina, querosene, diesel, entre outros."}, {"id": 2000003766, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pergunta", "frente": "Qual a principal contribuição do modelo de Rutherford?", "verso": "O átomo tem um núcleo pequeno, denso e positivo, com elétrons girando ao redor, e é em grande parte vazio.", "explicacao": "Experimento da folha de ouro."}, {"id": 2000003767, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pergunta", "frente": "Qual a contribuição do modelo de Bohr?", "verso": "Os elétrons ocupam níveis de energia definidos e, ao mudar de nível, absorvem ou emitem energia (luz).", "explicacao": "Explica as cores dos fogos de artifício e dos testes de chama."}, {"id": 2000003768, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pergunta", "frente": "Quantos prótons, nêutrons e elétrons tem o átomo neutro de sódio (Z = 11, A = 23)?", "verso": "11 prótons, 12 nêutrons e 11 elétrons.", "explicacao": "Nêutrons = A − Z."}, {"id": 2000003769, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "O que são os metais alcalinos?", "verso": "Elementos da família 1 (exceto o hidrogênio), como sódio e potássio, muito reativos com a água.", "explicacao": "Têm 1 elétron na camada de valência."}, {"id": 2000003770, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "O que são os halogênios?", "verso": "Elementos da família 17, como flúor, cloro, bromo e iodo, muito reativos.", "explicacao": "Têm 7 elétrons na camada de valência."}, {"id": 2000003771, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "O que diz a regra do octeto?", "verso": "Os átomos tendem a ganhar, perder ou compartilhar elétrons para ficar com 8 elétrons na camada de valência, como os gases nobres.", "explicacao": "Explica a formação das ligações químicas."}, {"id": 2000003772, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "O que são forças intermoleculares de hidrogênio (pontes de hidrogênio)?", "verso": "Atrações fortes entre moléculas em que o H está ligado a F, O ou N.", "explicacao": "Explicam o alto ponto de ebulição da água."}, {"id": 2000003773, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "Por que o gelo flutua na água?", "verso": "Porque, ao congelar, as ligações de hidrogênio organizam as moléculas em uma estrutura mais espaçada, e o gelo fica menos denso que a água líquida.", "explicacao": "Isso protege a vida aquática no inverno."}, {"id": 2000003774, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "O que significa \"semelhante dissolve semelhante\"?", "verso": "Substâncias polares dissolvem polares e apolares dissolvem apolares.", "explicacao": "Por isso o óleo (apolar) não se mistura com a água (polar)."}, {"id": 2000003775, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "O que são sais?", "verso": "Compostos iônicos formados na reação entre ácido e base (neutralização).", "explicacao": "Ex.: NaCl (sal de cozinha)."}, {"id": 2000003776, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "O que é uma reação de neutralização?", "verso": "Reação entre ácido e base que forma sal e água.", "explicacao": "Ex.: HCl + NaOH → NaCl + H₂O."}, {"id": 2000003777, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "O que são óxidos ácidos e qual sua relação com a chuva ácida?", "verso": "Óxidos como SO₂, SO₃ e NO₂, que reagem com a água formando ácidos.", "explicacao": "Liberados pela queima de combustíveis fósseis."}, {"id": 2000003778, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "Por que o leite de magnésia é usado contra acidez estomacal?", "verso": "Porque é uma base fraca (hidróxido de magnésio) que neutraliza o excesso de ácido clorídrico no estômago.", "explicacao": "Reação de neutralização."}, {"id": 2000003779, "trilha": "enem", "materia": "qui", "assunto": "pH", "tipo": "pergunta", "frente": "Uma solução com pH 3 é quantas vezes mais ácida que outra com pH 5?", "verso": "100 vezes.", "explicacao": "Cada unidade de pH corresponde a um fator 10 na concentração de H⁺."}, {"id": 2000003780, "trilha": "enem", "materia": "qui", "assunto": "pH", "tipo": "pergunta", "frente": "O que são indicadores ácido-base?", "verso": "Substâncias que mudam de cor conforme o pH, como a fenolftaleína e o extrato de repolho roxo.", "explicacao": "A fenolftaleína fica rosa em meio básico."}, {"id": 2000003781, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "Qual a massa molar da água (H = 1, O = 16)?", "verso": "18 g/mol.", "explicacao": "2 × 1 + 16."}, {"id": 2000003782, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "Qual o volume de 1 mol de gás nas CNTP?", "verso": "22,4 litros.", "explicacao": "Condições normais de temperatura e pressão (0 °C e 1 atm)."}, {"id": 2000003783, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "Quantos mols há em 88 g de CO₂ (C = 12, O = 16)?", "verso": "2 mol.", "explicacao": "Massa molar 44 g/mol; 88 ÷ 44."}, {"id": 2000003784, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "O que diz a lei de Proust?", "verso": "Uma substância é sempre formada pelas mesmas proporções em massa de seus elementos.", "explicacao": "Lei das proporções definidas."}, {"id": 2000003785, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "Quantos gramas de sal há em 2 litros de solução de 15 g/L?", "verso": "30 g.", "explicacao": "15 × 2."}, {"id": 2000003786, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "Diluindo 100 mL de solução de 20 g/L até 400 mL, qual a nova concentração?", "verso": "5 g/L.", "explicacao": "C1 × V1 = C2 × V2: 20 × 100 = C2 × 400."}, {"id": 2000003787, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "O que é solubilidade?", "verso": "A quantidade máxima de soluto que se dissolve em certa quantidade de solvente, a uma dada temperatura.", "explicacao": "Acima dela, a solução fica saturada com corpo de fundo."}, {"id": 2000003788, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "Por que o refrigerante perde gás mais rápido quando está quente?", "verso": "Porque a solubilidade dos gases em líquidos diminui com o aumento da temperatura.", "explicacao": "Também diminui com a redução da pressão (ao abrir a garrafa)."}, {"id": 2000003789, "trilha": "enem", "materia": "qui", "assunto": "Propriedades coligativas", "tipo": "pergunta", "frente": "Por que a água com sal ferve a uma temperatura maior que a água pura?", "verso": "Pela ebulioscopia: o soluto não volátil dificulta a evaporação e eleva o ponto de ebulição.", "explicacao": "Propriedade coligativa."}, {"id": 2000003790, "trilha": "enem", "materia": "qui", "assunto": "Termoquímica", "tipo": "pergunta", "frente": "O que é entalpia (ΔH) negativa?", "verso": "Indica reação exotérmica, que libera calor.", "explicacao": "ΔH positivo indica reação endotérmica."}, {"id": 2000003791, "trilha": "enem", "materia": "qui", "assunto": "Termoquímica", "tipo": "pergunta", "frente": "Por que a dissolução de certos sais em água deixa o recipiente frio?", "verso": "Porque o processo é endotérmico: absorve calor do ambiente.", "explicacao": "Usado em bolsas de gelo instantâneo."}, {"id": 2000003792, "trilha": "enem", "materia": "qui", "assunto": "Cinética", "tipo": "pergunta", "frente": "Por que alimentos estragam mais devagar na geladeira?", "verso": "Porque a temperatura menor diminui a velocidade das reações químicas e da ação de microrganismos.", "explicacao": "Fator temperatura na cinética."}, {"id": 2000003793, "trilha": "enem", "materia": "qui", "assunto": "Cinética", "tipo": "pergunta", "frente": "Por que um comprimido efervescente triturado dissolve mais rápido?", "verso": "Porque aumenta a superfície de contato com a água.", "explicacao": "Fator superfície de contato."}, {"id": 2000003794, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pergunta", "frente": "O que acontece no ânodo e no cátodo de uma pilha?", "verso": "No ânodo ocorre oxidação (perda de elétrons, polo negativo). No cátodo ocorre redução (ganho de elétrons, polo positivo).", "explicacao": "Os elétrons vão do ânodo para o cátodo."}, {"id": 2000003795, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pergunta", "frente": "Por que a ferrugem se forma mais rápido perto do mar?", "verso": "Porque a maresia (água com sais) acelera a oxidação do ferro.", "explicacao": "A ferrugem é óxido de ferro hidratado."}, {"id": 2000003796, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "Que função orgânica tem o grupo –CHO?", "verso": "Aldeído.", "explicacao": "Ex.: formol (metanal)."}, {"id": 2000003797, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "Que função orgânica tem o grupo C=O entre dois carbonos?", "verso": "Cetona.", "explicacao": "Ex.: acetona (propanona)."}, {"id": 2000003798, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "Que função orgânica tem o grupo –NH₂ ligado a carbono?", "verso": "Amina.", "explicacao": "Aminas têm cheiro característico, como de peixe."}, {"id": 2000003799, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "Qual a fórmula e a função do etanol?", "verso": "C₂H₅OH (C₂H₆O), um álcool.", "explicacao": "Combustível e base das bebidas alcoólicas."}, {"id": 2000003800, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "O que é isomeria óptica?", "verso": "Moléculas com a mesma fórmula, mas que são imagens especulares não sobrepostas, por terem carbono quiral (assimétrico).", "explicacao": "Pode mudar o efeito de medicamentos, como no caso da talidomida."}, {"id": 2000003801, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "O que é a reação de esterificação?", "verso": "Reação entre ácido carboxílico e álcool que forma éster e água.", "explicacao": "Ésteres dão aroma a frutas."}, {"id": 2000003802, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "O que são gorduras trans?", "verso": "Gorduras produzidas na hidrogenação parcial de óleos vegetais, associadas a doenças cardiovasculares.", "explicacao": "Presentes em alguns alimentos industrializados."}, {"id": 2000003803, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "pergunta", "frente": "O que é o biodiesel?", "verso": "Combustível renovável obtido de óleos vegetais ou gorduras animais por transesterificação com álcool.", "explicacao": "Libera glicerina como subproduto."}, {"id": 2000003804, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "Por que o mercúrio é perigoso na cadeia alimentar?", "verso": "Porque se acumula nos tecidos e aumenta de concentração a cada nível trófico (bioacumulação e biomagnificação).", "explicacao": "Peixes predadores concentram mais."}, {"id": 2000003805, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "Por que se adiciona cloro à água tratada?", "verso": "Para matar microrganismos (desinfecção).", "explicacao": "Etapa final do tratamento, junto com o flúor."}, {"id": 2000003806, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "Por que se adiciona flúor à água de abastecimento?", "verso": "Para prevenir cáries.", "explicacao": "Política de saúde pública no Brasil."}, {"id": 2000003807, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "O que é o descarte correto de pilhas e baterias e por quê?", "verso": "Devolver em pontos de coleta, porque contêm metais pesados (como mercúrio, cádmio e chumbo) que contaminam solo e água.", "explicacao": "Logística reversa."}, {"id": 2000003808, "trilha": "enem", "materia": "qui", "assunto": "Radioatividade", "tipo": "pergunta", "frente": "Para que se usa o carbono-14?", "verso": "Para datar materiais orgânicos antigos, como fósseis e objetos arqueológicos, pela sua meia-vida de cerca de 5.730 anos.", "explicacao": "Datação radiométrica."}, {"id": 2000003809, "trilha": "enem", "materia": "qui", "assunto": "Radioatividade", "tipo": "pergunta", "frente": "O que foi o acidente com o césio-137 em Goiânia?", "verso": "Em 1987, uma cápsula de equipamento de radioterapia abandonado foi aberta, contaminando pessoas com material radioativo.", "explicacao": "O maior acidente radiológico do Brasil."}, {"id": 2000003810, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Um carro percorre 150 km em 2 horas. Qual a velocidade média?", "verso": "75 km/h.", "explicacao": "v = Δs ÷ Δt."}, {"id": 2000003811, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Um carro sai do repouso e chega a 20 m/s em 5 s. Qual a aceleração média?", "verso": "4 m/s².", "explicacao": "a = Δv ÷ Δt."}, {"id": 2000003812, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Qual a fórmula de Torricelli?", "verso": "v² = v₀² + 2 × a × Δs.", "explicacao": "Útil quando o tempo não é dado."}, {"id": 2000003813, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Uma pedra é solta de 20 m de altura. Quanto tempo leva para cair (g = 10 m/s²)?", "verso": "2 segundos.", "explicacao": "h = g × t² ÷ 2: 20 = 5 × t²."}, {"id": 2000003814, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Qual a velocidade de um objeto em queda livre após 3 s (g = 10 m/s²)?", "verso": "30 m/s.", "explicacao": "v = g × t."}, {"id": 2000003815, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "O que é velocidade relativa?", "verso": "A velocidade de um corpo em relação a outro. Mesmo sentido: subtraem-se as velocidades; sentidos opostos: somam-se.", "explicacao": "Ex.: dois carros a 80 km/h em sentidos opostos se aproximam a 160 km/h."}, {"id": 2000003816, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "O que é aceleração centrípeta?", "verso": "Aceleração dirigida ao centro da curva, que muda a direção da velocidade: a = v² ÷ R.", "explicacao": "Presente em qualquer movimento circular."}, {"id": 2000003817, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Qual o peso de um corpo de 60 kg na Terra (g = 10 m/s²)?", "verso": "600 N.", "explicacao": "P = m × g."}, {"id": 2000003818, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Por que o cinto de segurança é importante, segundo a 1ª lei de Newton?", "verso": "Porque, numa freada brusca, o corpo tende a continuar em movimento (inércia) e seria lançado para a frente.", "explicacao": "O cinto aplica a força que freia o corpo."}, {"id": 2000003819, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Qual força mantém um satélite em órbita?", "verso": "A força gravitacional, que atua como força centrípeta.", "explicacao": "Lei da gravitação universal de Newton."}, {"id": 2000003820, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "O que diz a lei da gravitação universal?", "verso": "Dois corpos se atraem com força proporcional ao produto de suas massas e inversamente proporcional ao quadrado da distância.", "explicacao": "F = G × m1 × m2 ÷ d²."}, {"id": 2000003821, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Um corpo de 5 kg recebe força resultante de 20 N. Qual a aceleração?", "verso": "4 m/s².", "explicacao": "a = F ÷ m."}, {"id": 2000003822, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Por que é mais fácil abrir uma porta empurrando longe da dobradiça?", "verso": "Porque o torque (momento) é força × distância ao eixo: quanto maior a distância, menor a força necessária.", "explicacao": "Princípio das alavancas."}, {"id": 2000003823, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Quais os tipos de alavanca?", "verso": "Interfixa (apoio no meio, como a tesoura), inter-resistente (resistência no meio, como o carrinho de mão) e interpotente (força no meio, como a pinça).", "explicacao": "Classificação pela posição do apoio, da força e da resistência."}, {"id": 2000003824, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Qual o trabalho realizado por uma força de 50 N que desloca um objeto por 4 m na mesma direção?", "verso": "200 J.", "explicacao": "τ = F × d."}, {"id": 2000003825, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Um objeto de 2 kg cai de 5 m. Qual a energia cinética ao chegar ao solo, sem atrito (g = 10 m/s²)?", "verso": "100 J.", "explicacao": "Toda a energia potencial (m × g × h = 2 × 10 × 5) vira cinética."}, {"id": 2000003826, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Uma máquina de 1.000 W realiza trabalho por 1 minuto. Quanta energia usa?", "verso": "60.000 J (60 kJ).", "explicacao": "E = P × t = 1.000 × 60."}, {"id": 2000003827, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Quanto é 1 kWh em joules?", "verso": "3,6 milhões de joules.", "explicacao": "1.000 W × 3.600 s."}, {"id": 2000003828, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Uma lâmpada de 10 W fica acesa 5 horas por dia durante 30 dias. Qual o consumo?", "verso": "1,5 kWh.", "explicacao": "10 W × 150 h = 1.500 Wh."}, {"id": 2000003829, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Por que lâmpadas de LED economizam energia?", "verso": "Porque têm maior rendimento: transformam mais energia elétrica em luz e menos em calor.", "explicacao": "Lâmpadas incandescentes desperdiçam a maior parte em calor."}, {"id": 2000003830, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Como funciona a energia solar fotovoltaica?", "verso": "Placas de silício transformam a luz do Sol diretamente em energia elétrica (efeito fotovoltaico).", "explicacao": "O aquecedor solar, diferente, só aquece a água."}, {"id": 2000003831, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Quais as desvantagens das usinas termelétricas a combustíveis fósseis?", "verso": "Emissão de gases de efeito estufa e poluentes, além do uso de recurso não renovável.", "explicacao": "São acionadas quando há pouca água nos reservatórios."}, {"id": 2000003832, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "Por que um navio de aço flutua?", "verso": "Porque seu formato oco desloca um volume de água cujo peso é igual ao peso do navio (empuxo).", "explicacao": "Princípio de Arquimedes."}, {"id": 2000003833, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "Como funciona o elevador hidráulico?", "verso": "Pelo princípio de Pascal: uma pequena força num êmbolo de área pequena gera grande força no êmbolo de área maior.", "explicacao": "F1 ÷ A1 = F2 ÷ A2."}, {"id": 2000003834, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "A cada quantos metros de profundidade na água a pressão aumenta cerca de 1 atm?", "verso": "A cada 10 metros.", "explicacao": "Teorema de Stevin."}, {"id": 2000003835, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "Por que o canudinho funciona?", "verso": "Ao sugar, diminuímos a pressão dentro do canudo, e a pressão atmosférica empurra o líquido para cima.", "explicacao": "Pressão atmosférica."}, {"id": 2000003836, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "Por que a água ferve a temperatura menor no alto de montanhas?", "verso": "Porque a pressão atmosférica é menor.", "explicacao": "Por isso cozinhar em altitude demora mais."}, {"id": 2000003837, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Quanta energia é preciso para aquecer 500 g de água de 20 °C a 60 °C (c = 1 cal/g°C)?", "verso": "20.000 cal (20 kcal).", "explicacao": "Q = m × c × ΔT = 500 × 1 × 40."}, {"id": 2000003838, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "O que é dilatação térmica e onde ela aparece?", "verso": "Aumento das dimensões de um corpo ao ser aquecido. Aparece nas juntas de dilatação de pontes e trilhos.", "explicacao": "Contração no resfriamento."}, {"id": 2000003839, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Por que a garrafa térmica conserva a temperatura?", "verso": "Porque o vácuo entre as paredes impede condução e convecção, e as paredes espelhadas refletem a irradiação.", "explicacao": "Bloqueia os três processos de propagação do calor."}, {"id": 2000003840, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Por que roupas escuras esquentam mais ao sol?", "verso": "Porque absorvem mais radiação; as claras refletem mais.", "explicacao": "Irradiação térmica."}, {"id": 2000003841, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "O que é equilíbrio térmico?", "verso": "Quando corpos em contato atingem a mesma temperatura e param de trocar calor.", "explicacao": "Lei zero da termodinâmica."}, {"id": 2000003842, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Como funciona a geladeira?", "verso": "Um gás refrigerante absorve calor do interior ao evaporar e libera calor fora (na grade traseira) ao condensar, com o trabalho do compressor.", "explicacao": "Máquina térmica funcionando ao contrário."}, {"id": 2000003843, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Uma onda tem frequência de 10 Hz e comprimento de 2 m. Qual a velocidade?", "verso": "20 m/s.", "explicacao": "v = λ × f."}, {"id": 2000003844, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Qual a velocidade aproximada do som no ar?", "verso": "Cerca de 340 m/s.", "explicacao": "No vácuo, o som não se propaga."}, {"id": 2000003845, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Por que vemos o relâmpago antes de ouvir o trovão?", "verso": "Porque a luz é muito mais rápida (cerca de 300.000 km/s) que o som (cerca de 340 m/s).", "explicacao": "Dá para estimar a distância da tempestade."}, {"id": 2000003846, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "O que é o eco?", "verso": "Reflexão do som que volta ao ouvinte com atraso suficiente para ser ouvida separadamente.", "explicacao": "O sonar usa o eco para medir distâncias."}, {"id": 2000003847, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "O que é difração?", "verso": "Capacidade da onda de contornar obstáculos e passar por fendas.", "explicacao": "Por isso ouvimos sons atrás de muros."}, {"id": 2000003848, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "O que é interferência de ondas?", "verso": "Superposição de ondas que pode reforçar (construtiva) ou anular (destrutiva) o efeito.", "explicacao": "Usada nos fones com cancelamento de ruído."}, {"id": 2000003849, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Qual a ordem das ondas eletromagnéticas da menor para a maior frequência?", "verso": "Rádio, micro-ondas, infravermelho, luz visível, ultravioleta, raios X e raios gama.", "explicacao": "Quanto maior a frequência, maior a energia."}, {"id": 2000003850, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Por que a radiação ultravioleta é perigosa?", "verso": "Porque tem energia suficiente para danificar o DNA das células da pele, aumentando o risco de câncer.", "explicacao": "O protetor solar bloqueia parte dela."}, {"id": 2000003851, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "O que é reflexão total e onde é usada?", "verso": "Quando a luz passa de um meio mais refringente para um menos refringente com ângulo acima do limite e é totalmente refletida. Usada na fibra óptica.", "explicacao": "Também explica o brilho do diamante."}, {"id": 2000003852, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Como é a imagem num espelho plano?", "verso": "Virtual, direita, do mesmo tamanho e simétrica (inverte esquerda e direita).", "explicacao": "Fica à mesma distância atrás do espelho."}, {"id": 2000003853, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Que tipo de espelho é usado nos retrovisores externos e por quê?", "verso": "Convexo, porque amplia o campo de visão, embora diminua a imagem.", "explicacao": "Espelhos côncavos ampliam imagens (como os de maquiagem)."}, {"id": 2000003854, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Que lente corrige a presbiopia (vista cansada)?", "verso": "Lente convergente.", "explicacao": "Dificuldade de ver de perto com a idade."}, {"id": 2000003855, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Por que o lápis parece quebrado dentro de um copo com água?", "verso": "Por causa da refração: a luz muda de velocidade e direção ao passar da água para o ar.", "explicacao": "Também faz piscinas parecerem mais rasas."}, {"id": 2000003856, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Como se forma o arco-íris?", "verso": "A luz do Sol sofre refração, dispersão e reflexão nas gotas de chuva, separando-se nas cores.", "explicacao": "O Sol fica atrás do observador."}, {"id": 2000003857, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Qual a corrente em um chuveiro de 4.400 W ligado em 220 V?", "verso": "20 A.", "explicacao": "P = U × i: 4.400 = 220 × i."}, {"id": 2000003858, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Qual a resistência de um aparelho que consome 2 A ligado em 110 V?", "verso": "55 Ω.", "explicacao": "R = U ÷ i."}, {"id": 2000003859, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Dois resistores de 10 Ω em paralelo equivalem a quanto?", "verso": "5 Ω.", "explicacao": "Iguais em paralelo: R ÷ n. Em série, somam: 20 Ω."}, {"id": 2000003860, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Por que as tomadas de uma casa são ligadas em paralelo?", "verso": "Para que todos os aparelhos recebam a mesma tensão e funcionem de forma independente.", "explicacao": "Em série, um aparelho desligado interromperia os outros."}, {"id": 2000003861, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "O que é curto-circuito?", "verso": "Ligação de baixíssima resistência entre os polos, que gera corrente muito alta e aquecimento, podendo causar incêndio.", "explicacao": "O disjuntor desarma para evitar."}, {"id": 2000003862, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "O que é eletrização por atrito?", "verso": "Quando dois corpos atritados trocam elétrons e ficam com cargas opostas.", "explicacao": "Ex.: pente atritado no cabelo atrai papel."}, {"id": 2000003863, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Por que a pessoa leva choque ao tocar o carro depois de sair dele em dias secos?", "verso": "Por descarga de eletricidade estática acumulada pelo atrito com o banco e o ar seco.", "explicacao": "Umidade facilita a descarga gradual."}, {"id": 2000003864, "trilha": "enem", "materia": "fis", "assunto": "Magnetismo", "tipo": "pergunta", "frente": "Como funciona a bússola?", "verso": "A agulha imantada se alinha ao campo magnético da Terra, apontando para o polo norte geográfico (que é um polo sul magnético).", "explicacao": "Polos opostos se atraem."}, {"id": 2000003865, "trilha": "enem", "materia": "fis", "assunto": "Magnetismo", "tipo": "pergunta", "frente": "Como funciona um gerador elétrico?", "verso": "Pela indução eletromagnética: o movimento de um ímã perto de uma bobina (ou da bobina no campo) gera corrente elétrica.", "explicacao": "Base das usinas hidrelétricas e eólicas."}, {"id": 2000003866, "trilha": "enem", "materia": "fis", "assunto": "Magnetismo", "tipo": "pergunta", "frente": "O que é um eletroímã?", "verso": "Bobina de fio enrolada num núcleo de ferro que vira ímã quando passa corrente elétrica.", "explicacao": "Usado em guindastes de ferro-velho e campainhas."}, {"id": 2000003867, "trilha": "enem", "materia": "fis", "assunto": "Física moderna", "tipo": "pergunta", "frente": "O que é o efeito fotoelétrico?", "verso": "Emissão de elétrons por um metal quando atingido por luz de frequência suficiente.", "explicacao": "Explicado por Einstein, base das células fotovoltaicas."}, {"id": 2000003868, "trilha": "enem", "materia": "fis", "assunto": "Física moderna", "tipo": "pergunta", "frente": "O que diz a famosa equação E = m × c²?", "verso": "Que massa e energia são equivalentes: uma pequena massa corresponde a enorme energia.", "explicacao": "Explica a energia das reações nucleares."}, {"id": 2000003869, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pergunta", "frente": "Quais as principais contribuições dos egípcios antigos?", "verso": "Escrita hieroglífica, matemática e geometria para medir terras, calendário solar, arquitetura monumental (pirâmides) e medicina.", "explicacao": "Civilização às margens do Nilo."}, {"id": 2000003870, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pergunta", "frente": "O que foi o Código de Hamurábi?", "verso": "Um dos primeiros códigos de leis escritas, da Mesopotâmia, baseado na lei de talião (\"olho por olho\").", "explicacao": "Século XVIII a.C."}, {"id": 2000003871, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pergunta", "frente": "Como era a sociedade espartana?", "verso": "Militarizada, com educação voltada à guerra, governo oligárquico e uso de servos (hilotas).", "explicacao": "Contraste com a democracia ateniense."}, {"id": 2000003872, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pergunta", "frente": "O que foi a política do \"pão e circo\" em Roma?", "verso": "Distribuição de alimentos e espetáculos à população pobre para evitar revoltas.", "explicacao": "Expressão usada até hoje para criticar governos."}, {"id": 2000003873, "trilha": "enem", "materia": "his", "assunto": "Idade Média", "tipo": "pergunta", "frente": "O que foram as Cruzadas?", "verso": "Expedições militares cristãs, entre os séculos XI e XIII, para conquistar Jerusalém e a Terra Santa.", "explicacao": "Reabriram rotas comerciais com o Oriente."}, {"id": 2000003874, "trilha": "enem", "materia": "his", "assunto": "Idade Média", "tipo": "pergunta", "frente": "O que foi a Peste Negra?", "verso": "Epidemia de peste bubônica no século XIV que matou cerca de um terço da população europeia.", "explicacao": "Contribuiu para a crise do feudalismo."}, {"id": 2000003875, "trilha": "enem", "materia": "his", "assunto": "Idade Média", "tipo": "pergunta", "frente": "O que foi o renascimento comercial e urbano na Baixa Idade Média?", "verso": "O crescimento das feiras, do comércio e das cidades (burgos) a partir do século XI, com o surgimento da burguesia.", "explicacao": "Ligado às Cruzadas e às novas rotas."}, {"id": 2000003876, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi o absolutismo?", "verso": "Regime em que o rei concentrava todos os poderes, justificado pelo direito divino.", "explicacao": "Ex.: Luís XIV (\"O Estado sou eu\")."}, {"id": 2000003877, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foram as Grandes Navegações?", "verso": "Expansão marítima europeia dos séculos XV e XVI, liderada por Portugal e Espanha, em busca de rotas para as Índias e de riquezas.", "explicacao": "Levou à chegada à América."}, {"id": 2000003878, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi o Tratado de Tordesilhas (1494)?", "verso": "Acordo entre Portugal e Espanha que dividiu as terras descobertas e a descobrir por uma linha imaginária.", "explicacao": "Depois superado pela expansão territorial do Brasil."}, {"id": 2000003879, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi a Contrarreforma?", "verso": "Reação da Igreja Católica à Reforma Protestante, com o Concílio de Trento, a Inquisição e a Companhia de Jesus.", "explicacao": "Século XVI."}, {"id": 2000003880, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi a Revolução Gloriosa (1688)?", "verso": "Revolução inglesa que estabeleceu a monarquia parlamentar e a Declaração de Direitos (Bill of Rights).", "explicacao": "Fim do absolutismo na Inglaterra."}, {"id": 2000003881, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi a independência dos Estados Unidos (1776)?", "verso": "Separação das 13 colônias da Inglaterra, inspirada no Iluminismo, que criou uma república federativa.", "explicacao": "Influenciou movimentos na América Latina."}, {"id": 2000003882, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "Quais as consequências da Segunda Guerra Mundial?", "verso": "Dezenas de milhões de mortos, o Holocausto, a criação da ONU (1945), a bipolarização entre EUA e URSS e a descolonização.", "explicacao": "Início da Guerra Fria."}, {"id": 2000003883, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi o Holocausto?", "verso": "O extermínio sistemático de cerca de 6 milhões de judeus, além de ciganos, homossexuais, pessoas com deficiência e opositores, pelo regime nazista.", "explicacao": "Genocídio que levou à Convenção sobre o Genocídio (1948)."}, {"id": 2000003884, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi o Plano Marshall?", "verso": "Ajuda econômica dos EUA para reconstruir a Europa Ocidental após a Segunda Guerra e conter o avanço do socialismo.", "explicacao": "Início da Guerra Fria."}, {"id": 2000003885, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que simbolizou a queda do Muro de Berlim (1989)?", "verso": "O fim da divisão da Alemanha e o colapso dos regimes socialistas do Leste Europeu.", "explicacao": "A URSS se dissolveu em 1991."}, {"id": 2000003886, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi a Guerra do Vietnã?", "verso": "Conflito em que os EUA apoiaram o Vietnã do Sul contra o Vietnã do Norte, socialista. Terminou com a vitória do Norte e a unificação em 1975.", "explicacao": "Grande movimento pacifista nos EUA."}, {"id": 2000003887, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi a Revolução Chinesa de 1949?", "verso": "Tomada do poder pelos comunistas liderados por Mao Tsé-Tung, que fundou a República Popular da China.", "explicacao": "Os nacionalistas foram para Taiwan."}, {"id": 2000003888, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi o New Deal?", "verso": "Política do presidente Roosevelt contra a crise de 1929, com obras públicas, intervenção do Estado na economia e direitos trabalhistas.", "explicacao": "Inspirado em ideias de Keynes."}, {"id": 2000003889, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foi a Revolução Iraniana de 1979?", "verso": "Revolução que derrubou o xá e instaurou uma república islâmica liderada pelo aiatolá Khomeini.", "explicacao": "Mudou a geopolítica do Oriente Médio."}, {"id": 2000003890, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "pergunta", "frente": "O que foram os atentados de 11 de setembro de 2001?", "verso": "Ataques terroristas da Al-Qaeda nos EUA, que derrubaram as Torres Gêmeas. Levaram à \"guerra ao terror\" e às invasões do Afeganistão e do Iraque.", "explicacao": "Marco da política internacional do século XXI."}, {"id": 2000003891, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi o Governo-Geral (1549)?", "verso": "Administração centralizada criada por Portugal para governar a colônia, com sede em Salvador. O primeiro governador foi Tomé de Sousa.", "explicacao": "Complementou as capitanias hereditárias."}, {"id": 2000003892, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foram as entradas e bandeiras?", "verso": "Expedições ao interior do Brasil: entradas eram oficiais; bandeiras, particulares, que caçavam indígenas e procuravam ouro.", "explicacao": "Ampliaram o território além de Tordesilhas."}, {"id": 2000003893, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi a invasão holandesa no Nordeste?", "verso": "Ocupação holandesa de parte do Nordeste açucareiro (1630–1654), com destaque para o governo de Maurício de Nassau em Pernambuco.", "explicacao": "Expulsos na Insurreição Pernambucana."}, {"id": 2000003894, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi o Tratado de Madri (1750)?", "verso": "Acordo entre Portugal e Espanha que reconheceu as terras ocupadas (uti possidetis), dando ao Brasil formato próximo do atual.", "explicacao": "Substituiu Tordesilhas."}, {"id": 2000003895, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi a Revolta de Beckman (1684)?", "verso": "Revolta no Maranhão contra o monopólio comercial da Companhia de Comércio e a proibição da escravização de indígenas.", "explicacao": "Revolta nativista."}, {"id": 2000003896, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi a Guerra dos Emboabas?", "verso": "Conflito em Minas Gerais (1707–1709) entre paulistas e forasteiros (\"emboabas\") pela posse das minas de ouro.", "explicacao": "Ciclo do ouro."}, {"id": 2000003897, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Confederação do Equador (1824)?", "verso": "Revolta republicana e separatista em Pernambuco contra o autoritarismo de D. Pedro I e a Constituição de 1824.", "explicacao": "Frei Caneca foi executado."}, {"id": 2000003898, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Revolta dos Malês (1835)?", "verso": "Revolta de africanos escravizados e libertos muçulmanos em Salvador.", "explicacao": "Uma das maiores revoltas de escravizados urbanos."}, {"id": 2000003899, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Farroupilha (1835–1845)?", "verso": "Revolta no Rio Grande do Sul de estancieiros contra a política fiscal do Império, que proclamou a República Rio-Grandense.", "explicacao": "A mais longa revolta do Império."}, {"id": 2000003900, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Cabanagem (1835–1840)?", "verso": "Revolta popular no Pará, com participação de indígenas, negros e mestiços pobres, que chegou a tomar o poder em Belém.", "explicacao": "Uma das revoltas regenciais mais sangrentas."}, {"id": 2000003901, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Guerra do Paraguai (1864–1870)?", "verso": "Guerra do Brasil, Argentina e Uruguai (Tríplice Aliança) contra o Paraguai, que terminou devastado.", "explicacao": "Fortaleceu o Exército brasileiro e enfraqueceu a monarquia."}, {"id": 2000003902, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Lei Eusébio de Queirós (1850)?", "verso": "Lei que proibiu o tráfico de africanos escravizados para o Brasil.", "explicacao": "Sob pressão da Inglaterra."}, {"id": 2000003903, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "Por que a imigração europeia cresceu no fim do século XIX?", "verso": "Para substituir a mão de obra escravizada nas lavouras de café e por uma política de \"branqueamento\" da população.", "explicacao": "Imigrantes italianos, alemães, espanhóis e depois japoneses."}, {"id": 2000003904, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "Como foi a Proclamação da República (1889)?", "verso": "Golpe militar liderado por Deodoro da Fonseca, com apoio de cafeicultores e republicanos, sem participação popular.", "explicacao": "Fim da monarquia."}, {"id": 2000003905, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi a Revolta da Armada?", "verso": "Revoltas da Marinha (1891 e 1893) contra os governos de Deodoro e Floriano Peixoto.", "explicacao": "Início turbulento da República."}, {"id": 2000003906, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi a Guerra do Contestado (1912–1916)?", "verso": "Conflito entre camponeses e o Estado na divisa entre Paraná e Santa Catarina, com forte caráter messiânico.", "explicacao": "Ligado à expulsão de posseiros para a construção de uma ferrovia."}, {"id": 2000003907, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi o tenentismo?", "verso": "Movimento de jovens oficiais do Exército nos anos 1920 contra as oligarquias da República Velha, com revoltas como a dos 18 do Forte e a Coluna Prestes.", "explicacao": "Pedia voto secreto e moralização política."}, {"id": 2000003908, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi a Revolução de 1930?", "verso": "Movimento que levou Getúlio Vargas ao poder e encerrou a República Velha e a política do café com leite.", "explicacao": "Início da Era Vargas."}, {"id": 2000003909, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi o Estado Novo (1937–1945)?", "verso": "Ditadura de Getúlio Vargas, com Constituição autoritária, censura (DIP), fechamento do Congresso e repressão.", "explicacao": "Também criou a CLT (1943)."}, {"id": 2000003910, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi a CLT?", "verso": "A Consolidação das Leis do Trabalho, de 1943, que reuniu os direitos trabalhistas, como carteira assinada, férias e jornada.", "explicacao": "Criada na Era Vargas."}, {"id": 2000003911, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi o populismo no Brasil (1945–1964)?", "verso": "Estilo político de líderes que buscavam apoio direto das massas urbanas, com discurso nacionalista e concessões trabalhistas.", "explicacao": "Ex.: Vargas e Jango."}, {"id": 2000003912, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "Por que João Goulart foi deposto em 1964?", "verso": "Por um golpe civil-militar, com apoio de setores empresariais, da classe média e dos EUA, contra suas reformas de base.", "explicacao": "Início da ditadura militar (1964–1985)."}, {"id": 2000003913, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "O que foi a Comissão Nacional da Verdade?", "verso": "Comissão (2012–2014) que investigou graves violações de direitos humanos cometidas por agentes do Estado, sobretudo na ditadura.", "explicacao": "Justiça de transição."}, {"id": 2000003914, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "pergunta", "frente": "Quando o Brasil teve a primeira eleição direta para presidente após a ditadura?", "verso": "Em 1989, vencida por Fernando Collor.", "explicacao": "Collor sofreu impeachment em 1992."}, {"id": 2000003915, "trilha": "enem", "materia": "his", "assunto": "América", "tipo": "pergunta", "frente": "O que foi a Revolução Mexicana (1910)?", "verso": "Revolução contra a ditadura de Porfírio Díaz, com participação camponesa (Zapata e Pancho Villa), que levou à reforma agrária.", "explicacao": "Primeira grande revolução social do século XX."}, {"id": 2000003916, "trilha": "enem", "materia": "his", "assunto": "América", "tipo": "pergunta", "frente": "O que foram as ditaduras militares do Cone Sul?", "verso": "Regimes militares dos anos 1960 a 1980 no Brasil, Argentina, Chile, Uruguai e Paraguai, apoiados pelos EUA no contexto da Guerra Fria.", "explicacao": "Cooperaram na repressão pela Operação Condor."}, {"id": 2000003917, "trilha": "enem", "materia": "his", "assunto": "África", "tipo": "pergunta", "frente": "O que foi a Conferência de Berlim (1884–1885)?", "verso": "Reunião de potências europeias que dividiu a África entre elas, sem considerar os povos locais.", "explicacao": "Marco do imperialismo."}, {"id": 2000003918, "trilha": "enem", "materia": "his", "assunto": "África", "tipo": "pergunta", "frente": "Quem foi Nelson Mandela?", "verso": "Líder sul-africano contra o apartheid, preso por 27 anos, que se tornou o primeiro presidente negro da África do Sul em 1994.", "explicacao": "Prêmio Nobel da Paz em 1993."}, {"id": 2000003919, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "Quantas horas de diferença há entre dois lugares com 45° de longitude de distância?", "verso": "3 horas.", "explicacao": "Cada fuso tem 15°: 45 ÷ 15 = 3."}, {"id": 2000003920, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "Se são 12h em Brasília (fuso −3), que horas são em Londres (fuso 0)?", "verso": "15h.", "explicacao": "Para o leste, as horas aumentam. Sem considerar o horário de verão britânico."}, {"id": 2000003921, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "O que é o GPS?", "verso": "Sistema de posicionamento por satélites que informa a latitude, a longitude e a altitude de um ponto.", "explicacao": "Muito usado em geotecnologias."}, {"id": 2000003922, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "O que é sensoriamento remoto?", "verso": "Obtenção de informações da superfície terrestre à distância, por satélites, aviões ou drones.", "explicacao": "Usado no monitoramento do desmatamento (ex.: Inpe)."}, {"id": 2000003923, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "O que é uma anamorfose?", "verso": "Mapa em que o tamanho dos territórios é alterado de acordo com um dado (como população ou PIB).", "explicacao": "Mostra desigualdades de forma visual."}, {"id": 2000003924, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pergunta", "frente": "O que causa terremotos e vulcões?", "verso": "O movimento das placas tectônicas, principalmente nas bordas onde elas se chocam ou se afastam.", "explicacao": "O Brasil fica no centro de uma placa, por isso tem poucos tremores fortes."}, {"id": 2000003925, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pergunta", "frente": "Por que o Brasil não tem cordilheiras como os Andes?", "verso": "Porque seu relevo é antigo e muito desgastado pela erosão, e o país fica no centro da Placa Sul-Americana.", "explicacao": "Os Andes são cadeias recentes, formadas pelo choque de placas."}, {"id": 2000003926, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pergunta", "frente": "O que são os combustíveis fósseis e onde se formam?", "verso": "Petróleo, carvão e gás natural, formados por restos orgânicos soterrados por milhões de anos, em bacias sedimentares.", "explicacao": "Recursos não renováveis."}, {"id": 2000003927, "trilha": "enem", "materia": "geo", "assunto": "Climatologia", "tipo": "pergunta", "frente": "Quais os principais climas do Brasil?", "verso": "Equatorial, tropical, tropical de altitude, tropical atlântico, semiárido e subtropical.", "explicacao": "O semiárido está no sertão nordestino."}, {"id": 2000003928, "trilha": "enem", "materia": "geo", "assunto": "Climatologia", "tipo": "pergunta", "frente": "O que são as massas de ar?", "verso": "Grandes porções de ar com temperatura e umidade semelhantes, que influenciam o tempo das regiões por onde passam.", "explicacao": "Ex.: massa polar atlântica traz frio ao Sul."}, {"id": 2000003929, "trilha": "enem", "materia": "geo", "assunto": "Climatologia", "tipo": "pergunta", "frente": "O que é a friagem?", "verso": "Queda brusca de temperatura na Amazônia causada pela chegada de massa de ar polar.", "explicacao": "Fenômeno que surpreende no clima quente."}, {"id": 2000003930, "trilha": "enem", "materia": "geo", "assunto": "Climatologia", "tipo": "pergunta", "frente": "O que é a La Niña?", "verso": "Resfriamento anormal das águas do Pacífico equatorial, com efeitos opostos ao El Niño no clima.", "explicacao": "No Brasil, tende a trazer mais chuva ao Norte e seca ao Sul."}, {"id": 2000003931, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "Qual a maior bacia hidrográfica do mundo?", "verso": "A Bacia Amazônica.", "explicacao": "Rio Amazonas: o maior em volume de água."}, {"id": 2000003932, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "Por que a Bacia do Paraná tem tantas hidrelétricas?", "verso": "Por ter rios de planalto, com desníveis, e estar perto dos grandes centros consumidores.", "explicacao": "Ex.: Itaipu."}, {"id": 2000003933, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "O que é a transposição do rio São Francisco?", "verso": "Obra que leva água do São Francisco para regiões do semiárido nordestino por canais.", "explicacao": "Debate sobre benefícios e impactos ambientais."}, {"id": 2000003934, "trilha": "enem", "materia": "geo", "assunto": "Biomas", "tipo": "pergunta", "frente": "Quais as características do Pampa?", "verso": "Bioma do Rio Grande do Sul, com campos de vegetação rasteira e clima subtropical, usado para pecuária.", "explicacao": "Ameaçado pela expansão de lavouras e silvicultura."}, {"id": 2000003935, "trilha": "enem", "materia": "geo", "assunto": "Biomas", "tipo": "pergunta", "frente": "O que é o arco do desmatamento?", "verso": "Faixa no sul e leste da Amazônia onde se concentra o desmatamento, ligado à pecuária, à soja e à grilagem.", "explicacao": "Avanço da fronteira agrícola."}, {"id": 2000003936, "trilha": "enem", "materia": "geo", "assunto": "Biomas", "tipo": "pergunta", "frente": "Quais as causas das queimadas no Cerrado e na Amazônia?", "verso": "Principalmente ação humana para abrir áreas de pasto e lavoura, agravada por secas.", "explicacao": "Liberam gases de efeito estufa."}, {"id": 2000003937, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é bônus demográfico?", "verso": "Período em que a população em idade ativa é maior que a dependente (crianças e idosos), favorecendo o crescimento econômico.", "explicacao": "O Brasil está saindo dessa fase."}, {"id": 2000003938, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é taxa de fecundidade?", "verso": "Número médio de filhos por mulher.", "explicacao": "No Brasil, está abaixo de 2,1, o nível de reposição."}, {"id": 2000003939, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é crescimento vegetativo?", "verso": "A diferença entre a taxa de natalidade e a de mortalidade.", "explicacao": "Não considera migrações."}, {"id": 2000003940, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é a PEA?", "verso": "A População Economicamente Ativa: pessoas que trabalham ou procuram trabalho.", "explicacao": "Base para calcular a taxa de desemprego."}, {"id": 2000003941, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é migração pendular?", "verso": "Deslocamento diário entre a cidade onde se mora e a cidade onde se trabalha ou estuda.", "explicacao": "Comum nas regiões metropolitanas."}, {"id": 2000003942, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é macrocefalia urbana?", "verso": "Crescimento excessivo de uma grande cidade em relação às demais da rede urbana.", "explicacao": "Comum em países com urbanização rápida."}, {"id": 2000003943, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é a rede urbana e a hierarquia urbana?", "verso": "Conjunto de cidades interligadas por fluxos; a hierarquia mostra a influência de cada uma (metrópoles nacionais, regionais, centros locais).", "explicacao": "Estudo Regic, do IBGE."}, {"id": 2000003944, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é mobilidade urbana sustentável?", "verso": "Priorizar transporte coletivo, bicicleta e caminhada, reduzindo congestionamentos e poluição.", "explicacao": "Política Nacional de Mobilidade Urbana (Lei 12.587/2012)."}, {"id": 2000003945, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é favelização?", "verso": "Crescimento de moradias precárias em áreas sem infraestrutura, resultado da desigualdade e do déficit habitacional.", "explicacao": "O IBGE passou a usar o termo \"favelas e comunidades urbanas\"."}, {"id": 2000003946, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que é o agronegócio exportador e quais seus principais produtos no Brasil?", "verso": "Produção agropecuária em grande escala voltada à exportação, com destaque para soja, milho, carne, café, açúcar e celulose.", "explicacao": "O Brasil é grande exportador de commodities."}, {"id": 2000003947, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que são commodities?", "verso": "Produtos primários padronizados negociados no mercado mundial, como soja, minério de ferro e petróleo.", "explicacao": "Preços definidos nas bolsas internacionais."}, {"id": 2000003948, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que é a reforma agrária?", "verso": "Redistribuição de terras improdutivas para trabalhadores sem terra, para reduzir a concentração fundiária.", "explicacao": "Prevista na Constituição (art. 184)."}, {"id": 2000003949, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que são agrotóxicos e quais seus riscos?", "verso": "Produtos químicos para controlar pragas, que podem contaminar alimentos, solo, água e trabalhadores.", "explicacao": "O Brasil é um dos maiores consumidores do mundo."}, {"id": 2000003950, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que é agroecologia?", "verso": "Produção agrícola que integra conhecimentos ecológicos e tradicionais, sem agrotóxicos, valorizando a agricultura familiar.", "explicacao": "Diferente da monocultura de exportação."}, {"id": 2000003951, "trilha": "enem", "materia": "geo", "assunto": "Indústria", "tipo": "pergunta", "frente": "O que é a guerra fiscal entre estados?", "verso": "Disputa entre estados que oferecem isenções de impostos para atrair indústrias.", "explicacao": "Contribuiu para a desconcentração industrial."}, {"id": 2000003952, "trilha": "enem", "materia": "geo", "assunto": "Indústria", "tipo": "pergunta", "frente": "O que é a Zona Franca de Manaus?", "verso": "Área com incentivos fiscais para atrair indústrias à Amazônia, com destaque para eletrônicos e motocicletas.", "explicacao": "Criada em 1967."}, {"id": 2000003953, "trilha": "enem", "materia": "geo", "assunto": "Energia", "tipo": "pergunta", "frente": "Qual a principal fonte de energia elétrica do Brasil?", "verso": "A hidrelétrica.", "explicacao": "A matriz elétrica brasileira é majoritariamente renovável."}, {"id": 2000003954, "trilha": "enem", "materia": "geo", "assunto": "Energia", "tipo": "pergunta", "frente": "O que é o etanol de cana e por que é estratégico para o Brasil?", "verso": "Combustível renovável produzido da cana-de-açúcar, usado em carros flex, que reduz a dependência do petróleo.", "explicacao": "Proálcool (1975)."}, {"id": 2000003955, "trilha": "enem", "materia": "geo", "assunto": "Globalização", "tipo": "pergunta", "frente": "O que são empresas transnacionais?", "verso": "Empresas com sede em um país e filiais em vários outros, que organizam a produção em escala mundial.", "explicacao": "Buscam mão de obra barata, incentivos e mercados."}, {"id": 2000003956, "trilha": "enem", "materia": "geo", "assunto": "Globalização", "tipo": "pergunta", "frente": "O que é a OMC?", "verso": "A Organização Mundial do Comércio, que regula o comércio internacional e resolve disputas entre países.", "explicacao": "Criada em 1995."}, {"id": 2000003957, "trilha": "enem", "materia": "geo", "assunto": "Globalização", "tipo": "pergunta", "frente": "O que é o meio técnico-científico-informacional (Milton Santos)?", "verso": "O espaço geográfico atual, marcado pela ciência, tecnologia e informação, que acelera os fluxos e aprofunda desigualdades.", "explicacao": "Conceito do geógrafo brasileiro."}, {"id": 2000003958, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é a ONU e quem tem poder de veto no Conselho de Segurança?", "verso": "Organização criada em 1945 para manter a paz. Têm veto EUA, Rússia, China, Reino Unido e França.", "explicacao": "Membros permanentes."}, {"id": 2000003959, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é a Otan?", "verso": "Aliança militar ocidental criada em 1949, liderada pelos EUA.", "explicacao": "Surgiu na Guerra Fria contra a URSS."}, {"id": 2000003960, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "Qual a origem do conflito entre Israel e Palestina?", "verso": "A disputa territorial após a criação do Estado de Israel em 1948, com guerras, ocupação de territórios e refugiados palestinos.", "explicacao": "Envolve questões religiosas, políticas e de soberania."}, {"id": 2000003961, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que foi o Protocolo de Kyoto?", "verso": "Acordo de 1997 que estabeleceu metas de redução de emissões de gases de efeito estufa para países desenvolvidos.", "explicacao": "Substituído na prática pelo Acordo de Paris (2015)."}, {"id": 2000003962, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é o mercado de créditos de carbono?", "verso": "Sistema em que quem reduz emissões pode vender créditos a quem precisa compensar suas emissões.", "explicacao": "Instrumento econômico contra o aquecimento global."}, {"id": 2000003963, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é o Código Florestal e o que são APPs?", "verso": "Lei que regula o uso da vegetação nativa. APPs (áreas de preservação permanente) são áreas protegidas como margens de rios e topos de morros.", "explicacao": "Lei 12.651/2012. Também prevê a reserva legal."}, {"id": 2000003964, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é assoreamento?", "verso": "Acúmulo de sedimentos no leito dos rios, geralmente pela retirada da mata ciliar.", "explicacao": "Diminui a profundidade e favorece enchentes."}, {"id": 2000003965, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é o lixão e por que deve ser substituído por aterro sanitário?", "verso": "Lixão é a disposição a céu aberto, que contamina solo e água (chorume) e atrai doenças. O aterro sanitário tem impermeabilização e tratamento.", "explicacao": "Política Nacional de Resíduos Sólidos."}, {"id": 2000003966, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "certo_errado", "frente": "Certo ou errado? Os decompositores são dispensáveis em um ecossistema equilibrado.", "verso": "Errado. Eles reciclam a matéria orgânica, devolvendo nutrientes ao ambiente.", "explicacao": "Sem eles, os nutrientes ficariam presos nos restos de seres mortos."}, {"id": 2000003967, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "certo_errado", "frente": "Certo ou errado? Um casal de olhos castanhos (heterozigotos) pode ter um filho de olhos azuis (recessivo).", "verso": "Certo. Aa × Aa pode gerar aa, com 25% de chance.", "explicacao": "Exemplo simplificado de herança mendeliana."}, {"id": 2000003968, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "certo_errado", "frente": "Certo ou errado? A dengue é transmitida de pessoa para pessoa pelo contato.", "verso": "Errado. É transmitida pela picada do mosquito Aedes aegypti infectado.", "explicacao": "O combate é eliminar a água parada."}, {"id": 2000003969, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "lacuna", "frente": "\"A organela responsável pela respiração celular aeróbica é a ____.\"", "verso": "mitocôndria", "explicacao": "Produz a maior parte do ATP da célula."}, {"id": 2000003970, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "certo_errado", "frente": "Certo ou errado? A dissolução do açúcar na água é uma transformação química.", "verso": "Errado. É física: o açúcar continua sendo açúcar, só que disperso na água.", "explicacao": "Na transformação química, surgem novas substâncias."}, {"id": 2000003971, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "certo_errado", "frente": "Certo ou errado? Ao diluir uma solução, a quantidade de soluto diminui.", "verso": "Errado. A quantidade de soluto é a mesma; só aumenta o volume de solvente, e a concentração cai.", "explicacao": "C1 × V1 = C2 × V2."}, {"id": 2000003972, "trilha": "enem", "materia": "qui", "assunto": "pH", "tipo": "lacuna", "frente": "\"Soluções com pH menor que 7 são ____; maiores que 7 são básicas.\"", "verso": "ácidas", "explicacao": "A 25 °C, pH 7 é neutro."}, {"id": 2000003973, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "certo_errado", "frente": "Certo ou errado? Na Lua, a massa de uma pessoa é menor que na Terra.", "verso": "Errado. A massa é a mesma; o que muda é o peso, porque a gravidade é menor.", "explicacao": "P = m × g."}, {"id": 2000003974, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "certo_errado", "frente": "Certo ou errado? Ligar vários aparelhos de alta potência no mesmo benjamim pode causar superaquecimento.", "verso": "Certo. A corrente total aumenta e pode aquecer a fiação.", "explicacao": "Risco de incêndio."}, {"id": 2000003975, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "lacuna", "frente": "\"A velocidade de uma onda é igual ao comprimento de onda multiplicado pela ____.\"", "verso": "frequência", "explicacao": "v = λ × f."}, {"id": 2000003976, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "certo_errado", "frente": "Certo ou errado? Vemos um objeto verde porque ele absorve a luz verde.", "verso": "Errado. Ele reflete a luz verde e absorve as outras cores.", "explicacao": "A cor percebida é a da luz refletida."}, {"id": 2000003977, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "certo_errado", "frente": "Certo ou errado? Um aumento de 50% seguido de um desconto de 50% volta ao valor original.", "verso": "Errado. O valor final é 75% do original: 1,5 × 0,5 = 0,75.", "explicacao": "Porcentagens sucessivas se multiplicam."}, {"id": 2000003978, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "certo_errado", "frente": "Certo ou errado? A média é sempre um dos valores do conjunto.", "verso": "Errado. A média pode não ser nenhum dos valores. Ex.: média de 1 e 2 é 1,5.", "explicacao": "A mediana de um conjunto ímpar ordenado é sempre um dos valores."}, {"id": 2000003979, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "lacuna", "frente": "\"O volume do cubo de aresta a é ____.\"", "verso": "a³", "explicacao": "Ex.: aresta 3 cm → 27 cm³."}, {"id": 2000003980, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "certo_errado", "frente": "Certo ou errado? Se uma moeda deu cara 5 vezes seguidas, a chance de dar coroa na próxima é maior.", "verso": "Errado. Cada lançamento é independente: a chance continua 1/2.", "explicacao": "Falácia do apostador."}, {"id": 2000003981, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "certo_errado", "frente": "Certo ou errado? A Lei do Ventre Livre (1871) libertou todos os escravizados com mais de 60 anos.", "verso": "Errado. Ela declarou livres os filhos de mulheres escravizadas nascidos a partir da lei. A dos sexagenários é a Lei Saraiva-Cotegipe (1885).", "explicacao": "Leis graduais antes da Lei Áurea (1888)."}, {"id": 2000003982, "trilha": "enem", "materia": "his", "assunto": "Brasil República", "tipo": "certo_errado", "frente": "Certo ou errado? O voto feminino no Brasil foi conquistado com a Constituição de 1988.", "verso": "Errado. Foi garantido no Código Eleitoral de 1932, na Era Vargas, e confirmado na Constituição de 1934.", "explicacao": "A Constituição de 1988 garantiu o voto facultativo aos analfabetos."}, {"id": 2000003983, "trilha": "enem", "materia": "his", "assunto": "Contemporânea", "tipo": "lacuna", "frente": "\"A Organização das Nações Unidas foi criada em ____, ao fim da Segunda Guerra Mundial.\"", "verso": "1945", "explicacao": "Carta de São Francisco."}, {"id": 2000003984, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "certo_errado", "frente": "Certo ou errado? O mercantilismo defendia o livre comércio sem interferência do Estado.", "verso": "Errado. Defendia forte intervenção do Estado, acúmulo de metais preciosos e balança comercial favorável.", "explicacao": "O livre comércio é ideia do liberalismo econômico (Adam Smith)."}, {"id": 2000003985, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "certo_errado", "frente": "Certo ou errado? Quanto maior a escala de um mapa, maior a área representada.", "verso": "Errado. Escala grande mostra área pequena com muitos detalhes; escala pequena mostra área grande com poucos detalhes.", "explicacao": "1:1.000 é maior que 1:1.000.000."}, {"id": 2000003986, "trilha": "enem", "materia": "geo", "assunto": "Climatologia", "tipo": "certo_errado", "frente": "Certo ou errado? Tempo e clima são a mesma coisa.", "verso": "Errado. Tempo é a condição atmosférica do momento; clima é o padrão médio ao longo de décadas.", "explicacao": "Pegadinha frequente."}, {"id": 2000003987, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "lacuna", "frente": "\"A taxa de fecundidade necessária para repor a população, sem migrações, é de cerca de ____ filhos por mulher.\"", "verso": "2,1", "explicacao": "Abaixo disso, a população tende a envelhecer e diminuir."}, {"id": 2000003988, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "certo_errado", "frente": "Certo ou errado? O buraco na camada de ozônio é a principal causa do aquecimento global.", "verso": "Errado. São problemas diferentes: o buraco de ozônio é causado por CFCs e aumenta a radiação ultravioleta; o aquecimento é causado pelos gases de efeito estufa.", "explicacao": "Confusão comum."}, {"id": 2000003989, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "certo_errado", "frente": "Certo ou errado? Para Sócrates, o conhecimento começa pelo reconhecimento da própria ignorância.", "verso": "Certo. \"Só sei que nada sei.\"", "explicacao": "Ponto de partida da busca pela verdade."}, {"id": 2000003990, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "certo_errado", "frente": "Certo ou errado? Para os empiristas, o conhecimento vem principalmente da razão, sem depender da experiência.", "verso": "Errado. Isso é o racionalismo. Para os empiristas, o conhecimento vem da experiência sensível.", "explicacao": "Empiristas: Locke, Hume. Racionalistas: Descartes."}, {"id": 2000003991, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "certo_errado", "frente": "Certo ou errado? Etnocentrismo é julgar outras culturas a partir dos valores da própria cultura.", "verso": "Certo.", "explicacao": "O relativismo cultural é a postura oposta."}, {"id": 2000003992, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "lacuna", "frente": "\"Para Kant, a ação moral é a que se faz por ____, e não por interesse ou inclinação.\"", "verso": "dever", "explicacao": "Ética deontológica."}, {"id": 2000003993, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "certo_errado", "frente": "Certo ou errado? Para o Enem, a variedade regional deve ser sempre corrigida para a norma-padrão.", "verso": "Errado. O Enem valoriza a variação linguística e combate o preconceito linguístico; o critério é a adequação ao contexto.", "explicacao": "A redação, porém, exige a norma-padrão."}, {"id": 2000003994, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "certo_errado", "frente": "Certo ou errado? O Arcadismo valorizava a vida simples no campo (bucolismo) e o equilíbrio clássico.", "verso": "Certo.", "explicacao": "Lemas: fugere urbem e carpe diem."}, {"id": 2000003995, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "lacuna", "frente": "\"Quando o foco está no emissor e em suas emoções, predomina a função ____.\"", "verso": "emotiva (expressiva)", "explicacao": "Uso da 1ª pessoa e de interjeições."}, {"id": 2000003996, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "certo_errado", "frente": "Certo ou errado? Na redação do Enem, desrespeitar os direitos humanos na proposta de intervenção zera a redação.", "verso": "Errado. Desde 2017, isso não zera a redação, mas tira pontos da competência 5.", "explicacao": "As regras de nota zero incluem fuga ao tema e não atender ao tipo textual."}, {"id": 2000003997, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "certo_errado", "frente": "Certo ou errado? Na função f(x) = −2x + 4, a reta é crescente.", "verso": "Errado. O coeficiente angular é negativo (−2), então a função é decrescente.", "explicacao": "Corta o eixo y em 4 e o eixo x em 2."}, {"id": 2000003998, "trilha": "enem", "materia": "qui", "assunto": "Química orgânica", "tipo": "certo_errado", "frente": "Certo ou errado? Todo composto que contém carbono é orgânico.", "verso": "Errado. CO₂, CO e carbonatos têm carbono, mas são considerados inorgânicos.", "explicacao": "Exceções clássicas."}, {"id": 2000003999, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "certo_errado", "frente": "Certo ou errado? As veias sempre transportam sangue pobre em oxigênio.", "verso": "Errado. As veias pulmonares levam sangue rico em oxigênio dos pulmões ao coração.", "explicacao": "Veia é definida pelo sentido (chega ao coração), não pelo tipo de sangue."}, {"id": 2000004000, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "certo_errado", "frente": "Certo ou errado? O cobertor esquenta o corpo porque produz calor.", "verso": "Errado. Ele é isolante térmico: diminui a perda do calor que o próprio corpo produz.", "explicacao": "Por isso não aquece um objeto frio."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
